	["GUIDE_TIP_278"] = "Vampiric Embrace converts some of your damage into healing for the group.",
	["GUIDE_TIP_279"] = "Garrote is your start; it applies bleed and generates Combo Points.",
	["GUIDE_TIP_280"] = "Rupture is your main finisher; always keep this bleed active on your target.",
	["GUIDE_TIP_281"] = "Backstab is your base builder for Combo Points when you are behind the target.",
	["GUIDE_TIP_282"] = "Dispatch is your powerful finisher when the enemy is low on life.",
	["GUIDE_TIP_283"] = "Vendetta marks your enemy for extra damage; use this for burst.",
	["GUIDE_TIP_284"] = "Vanish makes you disappear in the middle of a fight; useful for escaping or reopening.",
	["GUIDE_TIP_285"] = "Kick interrupts enemy spells; essential to prevent damage.",
	["GUIDE_TIP_286"] = "Shadowstep lets you appear directly behind your target.",
	["GUIDE_TIP_287"] = "Evasion greatly increases your dodge chance when you take physical hits.",
	["GUIDE_TIP_288"] = "Cloak of Shadows makes you immune to magic and removes adverse effects.",
	["GUIDE_TIP_289"] = "Sinister Strike is your main attack to build up Combo Points.",
	["GUIDE_TIP_290"] = "Roll the Bones gives you random combat bonuses; always keep this active.",
	["GUIDE_TIP_291"] = "Eviscerate is your standard high damage finisher.",
	["GUIDE_TIP_292"] = "Use Pistol Shot when 'Opportunity' lights up for free Combo Points.",
	["GUIDE_TIP_293"] = "Blade Flurry ensures that your attacks hit all nearby enemies; ideal for groups.",
	["GUIDE_TIP_294"] = "Adrenaline Rush greatly increases your Energy generation and attack speed.",
	["GUIDE_TIP_295"] = "Blind disorients an enemy for a minute; perfect for crowd control.",
	["GUIDE_TIP_296"] = "Vanish is your emergency button to escape from dangerous situations.",
	["GUIDE_TIP_297"] = "Kick those annoying wizards to stop their spells.",
	["GUIDE_TIP_298"] = "Feint reduces the damage you take from area attacks (AoE).",
	["GUIDE_TIP_299"] = "Shadowstrike is your strongest opener and Combo Point builder from Stealth or Shadow Dance.",
	["GUIDE_TIP_300"] = "Eviscerate is your primary finisher for maximum damage.",
	["GUIDE_TIP_301"] = "Black Powder is your finisher for groups of enemies.",
	["GUIDE_TIP_302"] = "Shadow Dance lets you use Stealth attacks without being invisible.",
	["GUIDE_TIP_303"] = "Shadow Blades ensures that your attacks do extra damage and generate more Combo Points.",
	["GUIDE_TIP_304"] = "Shuriken Tornado is perfect for infecting an entire group of enemies with diseases at once.",
	["GUIDE_TIP_305"] = "Vanish resets your stealth capabilities in the middle of a battle.",
	["GUIDE_TIP_306"] = "Kick is essential to interrupt enemies.",
	["GUIDE_TIP_307"] = "Kidney Shot stuns (stuns) an enemy based on your Combo Points.",
	["GUIDE_TIP_308"] = "Cloak of Shadows protects you from all magical attacks.",
	["GUIDE_TIP_309"] = "Lightning Bolt is your basic attack to build up Maelstrom.",
	["GUIDE_TIP_310"] = "Chain Lightning is your best weapon against groups of enemies.",
	["GUIDE_TIP_311"] = "Earth Shock is your powerful finisher; use it when your Maelstrom is almost full.",
	["GUIDE_TIP_312"] = "Lava Burst is guaranteed to deal critical damage if Flame Shock is on the target.",
	["GUIDE_TIP_313"] = "Always keep Flame Shock active on your enemies for constant damage.",
	["GUIDE_TIP_314"] = "Fire Elemental increases the damage of your Lava Burst and generates Maelstrom.",
	["GUIDE_TIP_315"] = "Astral Shift reduces incoming damage by 40%; your main defense.",
	["GUIDE_TIP_316"] = "Wind Shear is the best interrupt in the game; use it often!",
	["GUIDE_TIP_317"] = "Capacitor Totem stuns all nearby enemies after 2 seconds.",
	["GUIDE_TIP_318"] = "Bloodlust (or Heroism) greatly increases the attack speed of the entire party.",
	["GUIDE_TIP_319"] = "Stormstrike is your main attack; use it as soon as it becomes available.",
	["GUIDE_TIP_320"] = "Rockbiter generates Maelstrom and boosts your next attacks.",
	["GUIDE_TIP_321"] = "Lava Lash is your secondary attack to spend Maelstrom.",
	["GUIDE_TIP_322"] = "Use Crash Lightning against groups to make your other attacks AoE as well.",
	["GUIDE_TIP_323"] = "Flame Shock should always be on your target for extra damage over time.",
	["GUIDE_TIP_324"] = "Feral Spirit summons two wolves that deal damage and generate Maelstrom for you.",
	["GUIDE_TIP_325"] = "Don't forget Astral Shift for heavy hits; it saves your life.",
	["GUIDE_TIP_326"] = "Wind Shear to instantly silence enemy wizards.",
	["GUIDE_TIP_327"] = "Use Capacitor Totem to gain breathing space in large groups.",
	["GUIDE_TIP_328"] = "Ghost Wolf helps you move quickly and ignore delays.",
	["GUIDE_TIP_329"] = "Riptide provides an immediate heal and a strong heal over time.",
	["GUIDE_TIP_330"] = "Chain Heal is the king of group healing; it jumps to injured allies.",
	["GUIDE_TIP_331"] = "Healing Wave is slow but efficient; use this when damage is low.",
	["GUIDE_TIP_332"] = "Healing Surge is your quick emergency healing for critical situations.",
	["GUIDE_TIP_333"] = "Healing Stream Totem provides passive healing to the group while you do other things.",
	["GUIDE_TIP_334"] = "Spirit Link Totem evens out the lives of everyone nearby; a real life saver.",
	["GUIDE_TIP_335"] = "Use Astral Shift to take less damage yourself while healing others.",
	["GUIDE_TIP_336"] = "As a healer, Wind Shear is also your job; stop those spells!",
	["GUIDE_TIP_337"] = "Elemental Mastery greatly increases your Haste for faster healing.",
	["GUIDE_TIP_338"] = "Healing Tide Totem is your strongest group healing cooldown; save this for major AOE damage.",
	["GUIDE_TIP_339"] = "Agony should always be on your target; it does more and more damage the longer it ticks.",
	["GUIDE_TIP_340"] = "Corruption is your basic curse for constant damage over time.",
	["GUIDE_TIP_341"] = "Unstable Affliction is your strongest curse; you can only have one active at a time.",
	["GUIDE_TIP_342"] = "Vile Taint is perfect for infecting an entire group of enemies with Agony at once.",
	["GUIDE_TIP_343"] = "Malefic Rapture deals massive damage to anyone bearing your curses.",
	["GUIDE_TIP_344"] = "Shadow Bolt is your filler spell to build up Soul Shards.",
	["GUIDE_TIP_345"] = "Keep your Soul Rot cooldown ready for extra damage on multiple targets.",
	["GUIDE_TIP_346"] = "Soul Fire does significant damage and instantly gives you a Soul Shard.",
	["GUIDE_TIP_347"] = "Demonic Circle lets you instantly teleport back to a safe place.",
	["GUIDE_TIP_348"] = "Don't forget to craft your Healthstone; it is your own free 'potion'.",
