	["GUIDE_TIP_350"] = "Call Dreadstalkers should be used immediately as soon as the cooldown is over.",
	["GUIDE_TIP_351"] = "Demonbolt generates 2 Soul Shards; use it when 'Demonic Core' lights up.",
	["GUIDE_TIP_352"] = "Summon Demonic Tyrant increases the duration of all your active demons and makes them stronger.",
	["GUIDE_TIP_353"] = "Implosion explodes all your Imps for massive damage to groups of enemies.",
	["GUIDE_TIP_354"] = "Shadow Bolt is your basic way to collect Soul Shards.",
	["GUIDE_TIP_355"] = "Demonic Strength lets your Felguard perform a powerful turn count.",
	["GUIDE_TIP_356"] = "Grimoire: Felguard summons a second guard for extra damage and a stun.",
	["GUIDE_TIP_357"] = "Unending Resolve reduces incoming damage and prevents your spells from being interrupted.",
	["GUIDE_TIP_358"] = "Keep your Voidwalker active while leveling so it takes all the hits.",
	["GUIDE_TIP_359"] = "Chaos Bolt is your strongest attack; use it to dump your Soul Shard Fragments.",
	["GUIDE_TIP_360"] = "Incinerate is your filler to build up Soul Shard Fragments.",
	["GUIDE_TIP_361"] = "Conflagrate is instant and gives you 'Backdraft', making your subsequent spells faster.",
	["GUIDE_TIP_362"] = "Immolate should always burn on your enemy for constant damage and extra fragments.",
	["GUIDE_TIP_363"] = "Summon Infernal is your big cooldown; it rains fire and paralyzes enemies on impact.",
	["GUIDE_TIP_364"] = "Rain of Fire is your best weapon against large groups of enemies.",
	["GUIDE_TIP_365"] = "Shadowburn is perfect for quickly killing off enemies with little life.",
	["GUIDE_TIP_366"] = "Havoc also lets your spells hit a second target; essential for 'cleave' damage.",
	["GUIDE_TIP_367"] = "Command Demon lets you use your active demon's special ability.",
	["GUIDE_TIP_368"] = "Use Unending Resolve when you know a big blow is coming.",
	["GUIDE_TIP_369"] = "Mortal Strike is your hardest blow; use it as soon as you can to spend Rage.",
	["GUIDE_TIP_370"] = "Overpower cannot be dodged and amplifies your next Mortal Strike.",
	["GUIDE_TIP_371"] = "Colossus Smash breaks your enemy's armor for massive damage phases.",
	["GUIDE_TIP_372"] = "Execute is your deadly finisher for enemies under 20% health.",
	["GUIDE_TIP_373"] = "Bladestorm turns you into a whirlwind of steel; ideal for groups of enemies.",
	["GUIDE_TIP_374"] = "Slam is your filler attack if you have too much Rage and other attacks are on cooldown.",
	["GUIDE_TIP_375"] = "Die by the Sword is your best defense; it blocks almost all physical attacks.",
	["GUIDE_TIP_376"] = "Pummel interrupts enemy spells; don't let those wizards cast!",
	["GUIDE_TIP_377"] = "Storm Bolt paralyzes (stun) an enemy from a distance; useful to stop danger.",
	["GUIDE_TIP_378"] = "Charge is the best way to immediately open the fight and build up Rage.",
	["GUIDE_TIP_379"] = "Rampage is your main attack; it makes you 'Enraged' for extra speed and damage.",
	["GUIDE_TIP_380"] = "Bloodthirst heals you a little bit and is your main builder of Rage.",
	["GUIDE_TIP_381"] = "Raging Blow does significant damage and can often be used twice in a row.",
	["GUIDE_TIP_382"] = "Execute builds up a ton of Rage and deals heavy damage to weak enemies.",
	["GUIDE_TIP_383"] = "Recklessness is your big cooldown; you get 100% more Rage and many more crits.",
	["GUIDE_TIP_384"] = "Whirlwind makes your next 2 attacks hit multiple enemies; essential for AoE.",
	["GUIDE_TIP_385"] = "Enraged Regeneration heals you immensely as long as you keep using Bloodthirst.",
	["GUIDE_TIP_386"] = "Use Pummel to instantly stop those annoying enemy spells.",
	["GUIDE_TIP_387"] = "Piercing Howl slows down all enemies around you; useful for control.",
	["GUIDE_TIP_388"] = "Heroic Leap lets you bridge great distances; perfect for mobility.",
	["GUIDE_TIP_389"] = "Shield Slam is your strongest threat attack and generates a lot of Rage.",
	["GUIDE_TIP_390"] = "Thunder Clap slows down enemies and keeps groups of monsters away from you.",
	["GUIDE_TIP_391"] = "Revenge hits back hard after a block or dodge; free damage against groups.",
	["GUIDE_TIP_392"] = "Shield Block should always be active when taking physical hits from monsters.",
	["GUIDE_TIP_393"] = "Ignore Pain absorbs a large portion of incoming damage; use your Rage on this.",
	["GUIDE_TIP_394"] = "Avatar turns you into a giant; you do more damage and break out of delays.",
	["GUIDE_TIP_395"] = "Shield Wall is your strongest defense; use this if things really threaten to go wrong.",
	["GUIDE_TIP_396"] = "Last Stand temporarily increases your maximum life; your ultimate emergency button.",
	["GUIDE_TIP_397"] = "Pummel is essential for forcing wizards towards you by stopping their casts.",
	["GUIDE_TIP_398"] = "Intercept (or Charge) helps you quickly get to enemies or allies.",
