merge(ns._mhLocales and ns._mhLocales.nlNL, {
	["GUIDE_TIP_001"] = "Houd Moonfire en Sunfire altijd actief op je doelwit voor schade over tijd.",
	["GUIDE_TIP_002"] = "Gebruik Wrath om Solar Eclipse te activeren en je natuurschade te verhogen.",
	["GUIDE_TIP_003"] = "Gebruik Starfire tijdens Lunar Eclipse om meerdere vijanden tegelijk te raken.",
	["GUIDE_TIP_004"] = "Starsurge is je krachtigste aanval; gebruik dit zodra je genoeg Astral Power hebt.",
	["GUIDE_TIP_005"] = "Starfall is perfect voor groepen monsters; het raakt alles in de buurt.",
	["GUIDE_TIP_006"] = "Vergeet Barkskin niet als je aangevallen wordt; het vermindert de schade.",
	["GUIDE_TIP_007"] = "Typhoon is handig om vijanden van je af te blazen als ze te dichtbij komen.",
	["GUIDE_TIP_008"] = "Soothe verwijdert woede (Enrage) van monsters; erg handig in dungeons.",
	["GUIDE_TIP_009"] = "Dash helpt je om snel te ontsnappen of sneller naar je volgende doel te rennen.",
	["GUIDE_TIP_010"] = "Blijf altijd in Moonkin Form voor meer schade en extra bepantsering.",
	["GUIDE_TIP_011"] = "Begin gevechten met Rake vanuit Prowl voor extra schade en een bleed.",
	["GUIDE_TIP_012"] = "Rip is je belangrijkste finisher; houd deze bleed altijd actief op sterke vijanden.",
	["GUIDE_TIP_013"] = "Gebruik Ferocious Bite als finisher als je vijand bijna dood is of je Rip al actief is.",
	["GUIDE_TIP_014"] = "Shred is je belangrijkste aanval om Combo Points op te bouwen.",
	["GUIDE_TIP_015"] = "Tiger's Fury geeft je direct Energy en verhoogt je schade; gebruik dit vaak!",
	["GUIDE_TIP_016"] = "Thrash raakt alle vijanden om je heen en laat ze bloeden; goed voor groepen.",
	["GUIDE_TIP_017"] = "Survival Instincts is je sterkste verdediging; gebruik dit bij grote gevaren.",
	["GUIDE_TIP_018"] = "Skull Bash onderbreekt vijandelijke toverspreuken en brengt je direct naar je doel.",
	["GUIDE_TIP_019"] = "Maim kan een vijand verdoven (stun) als je ze even stil wilt zetten.",
	["GUIDE_TIP_020"] = "Predatory Swiftness zorgt dat je Regrowth soms direct en gratis kunt gebruiken.",
	["GUIDE_TIP_021"] = "Gebruik Moonfire om van veraf te trekken — veiliger dan in het gezicht springen.",
	["GUIDE_TIP_022"] = "Bear Form is jouw tank-vorm tijdens het levelen — blijf daar in als je klappen krijgt.",
	["GUIDE_TIP_023"] = "Ironfur tegen fysieke klappen: niet vergeten bij elites en rares.",
	["GUIDE_TIP_024"] = "Growl helpt als een andere speler per ongeluk dreiging pakt.",
	["GUIDE_TIP_025"] = "Thrash bij meerdere vijanden; houd het actief voor AOE-dreiging.",
	["GUIDE_TIP_026"] = "Mangle is een belangrijke bouwsteen — gebruik het vaak.",
	["GUIDE_TIP_027"] = "Barkskin is voor ‘oeps’-momenten — niet te lang bewaren tot je bijna dood bent.",
	["GUIDE_TIP_028"] = "Frenzied Regeneration: genees op tijd, niet pas op het allerlaatste moment.",
	["GUIDE_TIP_029"] = "Houd Mark of the Wild actief; deze gratis buff geeft extra stats en maakt elke pull net wat veiliger.",
	["GUIDE_TIP_030"] = "Skull Bash onderbreekt vijandelijke casts — leer hem klaar te hebben in kerkers.",
	["GUIDE_TIP_031"] = "Houd Rejuvenation altijd actief op de tank voor constante healing.",
	["GUIDE_TIP_032"] = "Lifebloom moet altijd op de tank staan; het geeft een grote genezing als het afgelopen is.",
	["GUIDE_TIP_033"] = "Gebruik Wild Growth als de hele groep schade krijgt.",
	["GUIDE_TIP_034"] = "Regrowth is je snelle heal voor noodgevallen.",
	["GUIDE_TIP_035"] = "Swiftmend geeft een directe grote heal, maar je moet eerst Rejuvenation op het doel hebben.",
	["GUIDE_TIP_036"] = "Leg Efflorescentie (de cirkel) neer op de plek waar de meeste mensen staan.",
	["GUIDE_TIP_037"] = "Gebruik Moonfire en Sunfire om mee te helpen met schade als er niemand doodgaat.",
	["GUIDE_TIP_038"] = "Ironbark vermindert de schade die de tank krijgt; gebruik dit bij grote klappen.",
	["GUIDE_TIP_039"] = "Gebruik Innervate op jezelf als je mana bijna op is en je veel moet healen.",
	["GUIDE_TIP_040"] = "Nature's Swiftness maakt je volgende Regrowth gratis en direct.",
	["GUIDE_TIP_041"] = "Death Strike is je belangrijkste knop; het geneest je en geeft een schild na schade.",
	["GUIDE_TIP_042"] = "Marrowrend bouwt Bone Shield op. Houd dit altijd boven de 5 stacks voor extra pantser.",
