	["GUIDE_TIP_044"] = "Leg Death and Decay neer bij groepen vijanden zodat je Heart Strike meerdere doelen raakt.",
	["GUIDE_TIP_045"] = "Blood Boil verspreidt je ziektes en helpt om de aandacht van alle monsters vast te houden.",
	["GUIDE_TIP_046"] = "Dancing Rune Weapon is een sterke verdediging die je helpt om aanvallen te pareren.",
	["GUIDE_TIP_047"] = "Vampiric Blood geeft je tijdelijk veel meer leven; gebruik dit als je in gevaar bent.",
	["GUIDE_TIP_048"] = "Anti-Magic Shell blokkeert magische schade en voorkomt dat je nadelige effecten krijgt.",
	["GUIDE_TIP_049"] = "Asphyxiate verlamt een vijand voor een paar seconden; handig om gevaarlijke spreuken te stoppen.",
	["GUIDE_TIP_050"] = "Death Grip trekt een vijand direct naar je toe. Perfect om vluchters terug te halen.",
	["GUIDE_TIP_051"] = "Frost Strike is je belangrijkste manier om Runic Power uit te geven.",
	["GUIDE_TIP_052"] = "Howling Blast brengt Frost Fever aan. Gebruik het altijd als de Rime-proc oplicht.",
	["GUIDE_TIP_053"] = "Obliterate is je hoofdaanval. Gebruik dit wanneer je Killing Machine procs hebt voor kritieke schade.",
	["GUIDE_TIP_054"] = "Remorseless Winter doet constante schade om je heen; ideaal voor groepen monsters.",
	["GUIDE_TIP_055"] = "Pillar of Frost verhoogt je Strength enorm; gebruik dit bij elk groot gevecht.",
	["GUIDE_TIP_056"] = "Empower Rune Weapon geeft je direct runes en Runic Power terug voor extra burst.",
	["GUIDE_TIP_057"] = "Chains of Ice vertraagt vijanden extreem; handig om afstand te houden of iemand te stoppen.",
	["GUIDE_TIP_058"] = "Mind Freeze is je 'kick' om toverspreuken van vijanden te onderbreken.",
	["GUIDE_TIP_059"] = "Vergeet Death Strike niet als je leven laag is; het kost Runic Power maar redt je leven.",
	["GUIDE_TIP_060"] = "Uitbraak besmet alle vijanden direct met virulente pest. Begin met elk gevecht.",
