	["GUIDE_TIP_337"] = "Elemental Mastery verhoogt je Haste enorm voor snellere genezing.",
	["GUIDE_TIP_338"] = "Healing Tide Totem is je sterkste groeps-heal cooldown; bewaar dit voor grote AOE schade.",
	["GUIDE_TIP_339"] = "Agony moet altijd op je doelwit staan; het doet steeds meer schade naarmate het langer tikt.",
	["GUIDE_TIP_340"] = "Corruption is je basis-vloek voor constante schade over tijd.",
	["GUIDE_TIP_341"] = "Unstable Affliction is je sterkste vloek; je kunt er maar één tegelijk actief hebben.",
	["GUIDE_TIP_342"] = "Vile Taint is perfect voor een hele groep vijanden die tegelijkertijd besmet zijn met Agony.",
	["GUIDE_TIP_343"] = "Malefic Rapture doet enorme schade aan iedereen die jouw vloeken draagt.",
	["GUIDE_TIP_344"] = "Shadow Bolt is je filler-spreuk om Soul Shards op te bouwen.",
	["GUIDE_TIP_345"] = "Houd je Soul Rot cooldown paraat voor extra schade op meerdere doelen.",
	["GUIDE_TIP_346"] = "Soul Fire doet flinke schade en geeft je direct een Soul Shard.",
	["GUIDE_TIP_347"] = "Demonic Circle laat je direct terug teleporteren naar een veilige plek.",
	["GUIDE_TIP_348"] = "Vergeet je Healthstone niet te maken; het is je eigen gratis 'potion'.",
	["GUIDE_TIP_349"] = "Hand of Gul'dan verbruikt je Soul Shards om Wild Imps op te roepen.",
	["GUIDE_TIP_350"] = "Call Dreadstalkers moet je direct gebruiken zodra de cooldown voorbij is.",
	["GUIDE_TIP_351"] = "Demonbolt hoofd 2 Soul Shards; gebruik het als 'Demonic Core' oplicht.",
	["GUIDE_TIP_352"] = "Summon Demonic Tyrant verlengt de duur van al je actieve demonen en maakt ze sterker.",
	["GUIDE_TIP_353"] = "Implosion laat al je Imps ontploffen voor enorme schade aan groepen vijanden.",
	["GUIDE_TIP_354"] = "Shadow Bolt is je basis-manier om Soul Shards te verzamelen.",
	["GUIDE_TIP_355"] = "Demonic Strength laat je Felguard een krachtige draaiaantal uitvoeren.",
	["GUIDE_TIP_356"] = "Grimoire: Felguard roept een tweede bewaker op voor extra schade en een stun.",
	["GUIDE_TIP_357"] = "Unending Resolve vermindert inkomende schade en voorkomt dat je spreuken worden onderbroken.",
	["GUIDE_TIP_358"] = "Houd je Voidwalker actief tijdens het levelen zodat hij alle klappen opvangt.",
	["GUIDE_TIP_359"] = "Chaos Bolt is je zwaarste aanval; gebruik het om je Soul Shard Fragments te lozen.",
	["GUIDE_TIP_360"] = "Incinerate is je filler om Soul Shard Fragments op te bouwen.",
	["GUIDE_TIP_361"] = "Conflagrate is instant en geeft je 'Backdraft', waardoor je volgende spreuken sneller gaan.",
	["GUIDE_TIP_362"] = "Immolate moet altijd op je vijand branden voor constante schade en extra fragmenten.",
	["GUIDE_TIP_363"] = "Summon Infernal is je grote cooldown; het regent vuur en verlamt vijanden bij de inslag.",
	["GUIDE_TIP_364"] = "Rain of Fire is je beste wapen tegen grote groepen vijanden.",
	["GUIDE_TIP_365"] = "Shadowburn is perfect om vijanden met weinig leven snel af te maken.",
	["GUIDE_TIP_366"] = "Havoc laat je spreuken ook een tweede doelwit raken; essentieel voor 'cleave' schade.",
	["GUIDE_TIP_367"] = "Command Demon laat je de speciale vaardigheid van je actieve demoon gebruiken.",
	["GUIDE_TIP_368"] = "Gebruik Unending Resolve als je weet dat er een grote klap aan komt.",
	["GUIDE_TIP_369"] = "Mortal Strike is je zwaarste klap; gebruik het zodra het kan om Rage uit te geven.",
	["GUIDE_TIP_370"] = "Overpower kan niet worden ontweken en versterkt je volgende Mortal Strike.",
	["GUIDE_TIP_371"] = "Colossus Smash breekt het pantser van je vijand voor enorme schade-fases.",
	["GUIDE_TIP_372"] = "Execute is je dodelijke finisher voor vijanden onder de 20% gezondheid.",
	["GUIDE_TIP_373"] = "Bladestorm verandert je in een wervelwind van staal; ideaal voor groepen vijanden.",
	["GUIDE_TIP_374"] = "Slam is je filler-aanval als je teveel Rage hebt en andere aanvallen op cooldown staan.",
	["GUIDE_TIP_375"] = "Die by the Sword is je beste verdediging; het blokkeert bijna alle fysieke aanvallen.",
	["GUIDE_TIP_376"] = "Pummel onderbreekt vijandelijke spreuken; laat die tovenaars niet casten!",
	["GUIDE_TIP_377"] = "Storm Bolt verlamt (stun) een vijand van een afstand; handig om gevaar te stoppen.",
	["GUIDE_TIP_378"] = "Charge is de beste manier om het gevecht direct te openen en Rage op te bouwen.",
	["GUIDE_TIP_379"] = "Rampage is je belangrijkste aanval; het maakt je 'Enraged' voor extra snelheid en schade.",
	["GUIDE_TIP_380"] = "Bloodthirst geneest je een klein beetje en is je hoofdbouwer van Rage.",
	["GUIDE_TIP_381"] = "Raging Blow doet flinke schade en kan vaak twee keer achter elkaar gebruikt worden.",
	["GUIDE_TIP_382"] = "Execute bouwt enorm veel Rage op en doet zware schade aan zwakke vijanden.",
	["GUIDE_TIP_383"] = "Recklessness is je grote cooldown; je krijgt 100% meer Rage en veel meer crits.",
	["GUIDE_TIP_384"] = "Whirlwind zorgt dat je volgende 2 aanvallen meerdere vijanden raken; essentieel voor AoE.",
	["GUIDE_TIP_385"] = "Enraged Regeneration geneest je enorm zolang je Bloodthirst blijft gebruiken.",
	["GUIDE_TIP_386"] = "Gebruik Pummel om die irritante spreuken van vijanden direct te stoppen.",
	["GUIDE_TIP_387"] = "Piercing Howl vertraagt alle vijanden om je heen; handig voor controle.",
	["GUIDE_TIP_388"] = "Heroic Leap laat je grote afstanden overbruggen; perfect voor mobiliteit.",
	["GUIDE_TIP_389"] = "Shield Slam is je sterkste aanval voor dreiging en genereert veel Rage.",
	["GUIDE_TIP_390"] = "Thunder Clap vertraagt vijanden en houdt groepen monsters bij je weg.",
	["GUIDE_TIP_391"] = "Revenge slaat hard terug na een blok of ontwijking; gratis schade tegen groepen.",
	["GUIDE_TIP_392"] = "Shield Block moet altijd actief zijn als je fysieke klappen opvangt van monsters.",
	["GUIDE_TIP_393"] = "Ignore Pain absorbeert een groot deel van de inkomende schade; gebruik je Rage hieraan.",
	["GUIDE_TIP_394"] = "Avatar verandert je in een reus; je doet meer schade en breekt uit vertragingen.",
	["GUIDE_TIP_395"] = "Shield Wall is je sterkste verdediging; gebruik dit als het écht fout dreigt te gaan.",
	["GUIDE_TIP_396"] = "Last Stand verhoogt tijdelijk je maximale leven; je ultieme noodknop.",
	["GUIDE_TIP_397"] = "Pummel is essentieel om tovenaars naar je toe te dwingen door hun casts te stoppen.",
	["GUIDE_TIP_398"] = "Intercept (of Charge) helpt je om snel bij vijanden of bondgenoten te komen.",
})

merge(ns._mhLocales and ns._mhLocales.deDE, {
	["GUIDE_TIP_001"] = "Halten Sie „Mondfeuer“ und „Sonnenfeuer“ immer auf Ihrem Ziel aktiv, um langfristigen Schaden zu verursachen.",
	["GUIDE_TIP_002"] = "Benutze Zorn, um „Sonnenfinsternis“ zu aktivieren und deinen Naturschaden zu erhöhen.",
	["GUIDE_TIP_003"] = "Benutze Starfire während der Mondfinsternis, um mehrere Feinde gleichzeitig zu treffen.",
	["GUIDE_TIP_004"] = "Starsurge ist Ihr stärkster Angriff; Benutze dies, sobald du genug Astralkraft hast.",
	["GUIDE_TIP_005"] = "Starfall ist perfekt für Gruppen von Monstern; es berührt alles in der Nähe.",
	["GUIDE_TIP_006"] = "Vergessen Sie Barkskin nicht, wenn Sie angegriffen werden. es reduziert den Schaden.",
	["GUIDE_TIP_007"] = "Taifun ist nützlich, um Feinde wegzublasen, wenn sie zu nahe kommen.",
	["GUIDE_TIP_008"] = "Beruhigen entfernt den Zorn (Enrage) von Monstern; sehr nützlich in Dungeons.",
	["GUIDE_TIP_009"] = "Dash hilft Ihnen, schnell zu entkommen oder schneller zu Ihrem nächsten Ziel zu rennen.",
	["GUIDE_TIP_010"] = "Bleiben Sie immer in Mondkin-Form, um mehr Schaden und zusätzliche Rüstung zu erhalten.",
	["GUIDE_TIP_011"] = "Beginnen Sie Kämpfe mit Rake von Prowl für zusätzlichen Schaden und Blutung.",
	["GUIDE_TIP_012"] = "Rip ist Ihr Haupt-Finisher; Lassen Sie diese Blutung bei starken Feinden immer aktiv.",
	["GUIDE_TIP_013"] = "Verwenden Sie „Ferocious Bite“ als Finisher, wenn Ihr Feind fast tot ist oder Ihr Rip bereits aktiv ist.",
	["GUIDE_TIP_014"] = "Shred ist Ihr Hauptangriff, um Combo-Punkte zu sammeln.",
	["GUIDE_TIP_015"] = "Tigerzorn gibt dir sofort Energie und erhöht deinen Schaden; Benutze das oft!",
	["GUIDE_TIP_016"] = "Thrash trifft alle Feinde um dich herum und lässt sie bluten; gut für Gruppen.",
	["GUIDE_TIP_017"] = "Überlebensinstinkte sind Ihre stärkste Verteidigung; Verwenden Sie dies bei größeren Gefahren.",
	["GUIDE_TIP_018"] = "„Skull Bash“ unterbricht gegnerische Zaubersprüche und führt Sie direkt zu Ihrem Ziel.",
	["GUIDE_TIP_019"] = "Maim kann einen Feind betäuben, wenn Sie ihn für einen Moment einfrieren möchten.",
	["GUIDE_TIP_020"] = "Predatory Swiftness stellt sicher, dass Sie Regrowth manchmal sofort und kostenlos nutzen können.",
	["GUIDE_TIP_021"] = "Verwenden Sie Moonfire, um aus der Ferne zu ziehen – sicherer, als ins Gesicht zu springen.",
	["GUIDE_TIP_022"] = "Die Bärenform ist die Form Ihres Panzers beim Levelaufstieg – bleiben Sie in dieser Form, wenn Sie einen Treffer einstecken.",
	["GUIDE_TIP_023"] = "Ironfur mildert physische Treffer – denken Sie daran bei Elite- und seltenen Waffen.",
	["GUIDE_TIP_024"] = "Growl hilft, wenn ein anderer Spieler versehentlich eine Bedrohung annimmt.",
	["GUIDE_TIP_025"] = "Zerschmettere mehrere Feinde; Halten Sie es für AOE-Bedrohung aktiv.",
	["GUIDE_TIP_026"] = "Mangle ist ein wichtiger Baustein – verwenden Sie ihn häufig.",
	["GUIDE_TIP_027"] = "Barkskin ist für „Ups“-Momente gedacht – bewahren Sie es nicht zu lange auf, bis Sie fast tot sind.",
	["GUIDE_TIP_028"] = "Rasende Regeneration: Heilt rechtzeitig, nicht in letzter Minute.",
	["GUIDE_TIP_029"] = "Halten Sie „Mark of the Wild“ aktiv; Dieser kostenlose Buff verleiht zusätzliche Werte und macht jeden Zug ein bisschen sicherer.",
	["GUIDE_TIP_030"] = "Skull Bash unterbricht gegnerische Zauber – lernen Sie, es in Dungeons bereitzuhalten.",
	["GUIDE_TIP_031"] = "Halten Sie die Verjüngung im Tank immer aktiv, um eine kontinuierliche Heilung zu gewährleisten.",
	["GUIDE_TIP_032"] = "Lifebloom muss immer am Tank sein; es gibt eine große Heilung, wenn es abläuft.",
	["GUIDE_TIP_033"] = "Benutzen Sie „Wildes Wachstum“, wenn die gesamte Gruppe Schaden erleidet.",
	["GUIDE_TIP_034"] = "Nachwachsen ist Ihre schnelle Heilung für Notfälle.",
	["GUIDE_TIP_035"] = "„Schnellheilung“ bewirkt sofort eine große Heilung, aber Sie müssen zuerst „Verjüngung“ auf dem Ziel haben.",
	["GUIDE_TIP_036"] = "Platzieren Sie Effloreszenz (den Kreis) dort, wo die meisten Menschen stehen.",
	["GUIDE_TIP_037"] = "Benutze Mondfeuer und Sonnenfeuer, um Schaden zu beseitigen, wenn niemand stirbt.",
	["GUIDE_TIP_038"] = "Ironbark verringert den Schaden, den der Tank erleidet; Verwenden Sie dies für große Hits.",
	["GUIDE_TIP_039"] = "Benutze „Innervate“ bei dir selbst, wenn du wenig Mana hast und viel heilen musst.",
	["GUIDE_TIP_040"] = "Nature's Swiftness sorgt dafür, dass Ihr nächstes Nachwachsen kostenlos und sofort erfolgt.",
	["GUIDE_TIP_041"] = "Death Strike ist Ihr wichtigster Knopf; Es heilt dich und verleiht dir nach Schaden einen Schild.",
	["GUIDE_TIP_042"] = "Marrowrend baut Knochenschild auf. Behalten Sie für zusätzliche Rüstung immer mehr als 5 Stapel bei.",
	["GUIDE_TIP_043"] = "Heart Strike ist Ihr Füllangriff zum Aufbau von Runenkraft, insbesondere in Death and Decay.",
	["GUIDE_TIP_044"] = "Führe Gruppen von Feinden Tod und Verfall zu, sodass dein Herzschlag mehrere Ziele trifft.",
	["GUIDE_TIP_045"] = "Blood Boil verbreitet deine Krankheiten und hilft, die Aufmerksamkeit aller Monster auf sich zu ziehen.",
	["GUIDE_TIP_046"] = "Dancing Rune Weapon ist eine starke Verteidigung, die Ihnen hilft, Angriffe abzuwehren.",
	["GUIDE_TIP_047"] = "Vampirblut gibt dir vorübergehend viel mehr Leben; Verwenden Sie dies, wenn Sie in Gefahr sind.",
	["GUIDE_TIP_048"] = "Anti-Magic Shell blockiert magischen Schaden und verhindert, dass Sie negative Auswirkungen erleiden.",
	["GUIDE_TIP_049"] = "„Ersticken“ lähmt einen Gegner für einige Sekunden; nützlich, um gefährliche Zauber zu stoppen.",
	["GUIDE_TIP_050"] = "Death Grip zieht einen Feind sofort zu dir. Perfekt zum Apportieren von Flüchtlingen.",
	["GUIDE_TIP_051"] = "Frost Strike ist Ihre wichtigste Möglichkeit, Runenkraft auszugeben.",
	["GUIDE_TIP_052"] = "Heulende Explosion löst Frostfieber aus. Verwenden Sie es immer, wenn der Rime-Proc aufleuchtet.",
	["GUIDE_TIP_053"] = "Auslöschen ist Ihr Hauptangriff. Verwenden Sie dies, wenn Sie Killing Machine-Auslöser für kritischen Schaden haben.",
	["GUIDE_TIP_054"] = "Der unbarmherzige Winter verursacht ständigen Schaden um dich herum; Ideal für Gruppen von Monstern.",
	["GUIDE_TIP_055"] = "„Säule des Frosts“ erhöht deine Stärke erheblich; Benutze dies in jeder größeren Schlacht.",
	["GUIDE_TIP_056"] = "„Empower Rune Weapon“ gibt Ihnen sofort Runen und Runenkraft für zusätzliche Explosionen zurück.",
	["GUIDE_TIP_057"] = "Eisketten verlangsamt Feinde extrem; nützlich, um Abstand zu halten oder jemanden anzuhalten.",
	["GUIDE_TIP_058"] = "Mind Freeze ist Ihr „Kick“, um gegnerische Zauber zu unterbrechen.",
	["GUIDE_TIP_059"] = "Vergessen Sie Death Strike nicht, wenn Ihr Leben niedrig ist. Es kostet Runenkraft, rettet aber Ihr Leben.",
	["GUIDE_TIP_060"] = "Outbreak infiziert sofort alle Feinde mit Virulent Plague. Beginnen Sie jeden Kampf damit.",
	["GUIDE_TIP_061"] = "„Schwärender Schlag“ fügt Ihrem Ziel „Schwärende Wunden“ zu.",
	["GUIDE_TIP_062"] = "Scourge Strike lässt die Eiternden Wunden explodieren und verursacht hohen Schaden.",
	["GUIDE_TIP_063"] = "Death Coil ist Ihr Spender für Runenkraft; es stärkt deinen Ghul.",
	["GUIDE_TIP_064"] = "Die Apokalypse beschwört Armeen von Untoten, indem sie Eiternde Wunden zur Explosion bringt. Verwenden Sie dies für Burst.",
	["GUIDE_TIP_065"] = "Dark Transformation verwandelt deinen Ghul in ein monströses Biest mit neuen Kräften.",
	["GUIDE_TIP_066"] = "Army of the Dead beschwört eine riesige Armee; Heben Sie sich das für die härtesten Bosse auf.",
	["GUIDE_TIP_067"] = "Kämpfe in deinem Tod und Verfall, sodass dein Geißelschlag mehrere Feinde gleichzeitig trifft.",
	["GUIDE_TIP_068"] = "Anti-Magic Shell ist wichtig, um Zaubersprüche im Kampf zu negieren.",
	["GUIDE_TIP_069"] = "Chaos Strike ist Ihr Hauptausgabemittel.",
	["GUIDE_TIP_070"] = "Benutze „Klingentanz“ als Abklingzeit für AoE.",
	["GUIDE_TIP_071"] = "Eye Beam gibt dir Metamorphose; benutze es oft.",
	["GUIDE_TIP_072"] = "Teufelsrausch für Bewegung und Schaden.",
	["GUIDE_TIP_073"] = "Unschärfe ist Ihre beste Verteidigung.",
	["GUIDE_TIP_074"] = "Rachsüchtiger Rückzug, um Wut zu erlangen.",
	["GUIDE_TIP_075"] = "Metamorphose für großen Ausbruch.",
	["GUIDE_TIP_076"] = "Feueropferaura für passiven AoE.",
	["GUIDE_TIP_077"] = "Unterbrechen, um Zauber zu unterbrechen.",
	["GUIDE_TIP_078"] = "Verbrauche Magie, um Feinde zu vertreiben.",
	["GUIDE_TIP_079"] = "Seelenschnitzer für großen Schaden/Heilungen.",
	["GUIDE_TIP_080"] = "Dämonenstacheln müssen aktiv sein, wenn sie physische Treffer einstecken.",
	["GUIDE_TIP_081"] = "Die Aura der Feuerverbrennung erzeugt Wut.",
	["GUIDE_TIP_082"] = "Teufelsvernichtung ist deine „oh-sh*t“-Heilung.",
	["GUIDE_TIP_083"] = "Siegel der Flamme für Pull/AoE.",
	["GUIDE_TIP_084"] = "Höllenschlag für Mobilität.",
	["GUIDE_TIP_085"] = "Frailty Stacks helfen Ihnen zu überleben.",
	["GUIDE_TIP_086"] = "Siegel der Stille für Zauberer.",
	["GUIDE_TIP_087"] = "Metamorphose für maximale HP.",
	["GUIDE_TIP_088"] = "Wirf Glaive, um Adds aufzunehmen.",
	["GUIDE_TIP_089"] = "Leerenblitz ist Ihr Hauptschadenszauber.",
	["GUIDE_TIP_090"] = "Benutze „Seelenverbraucher“, um zu heilen.",
	["GUIDE_TIP_091"] = "Essence Tear für AoE-Schaden.",
	["GUIDE_TIP_092"] = "Void Metamorphosis ist Ihr großer Durchbruch.",
	["GUIDE_TIP_093"] = "Chaos Nova für Betäubung.",
	["GUIDE_TIP_094"] = "Spectral Sight, um versteckte Feinde zu finden.",
	["GUIDE_TIP_095"] = "Inhaftierung wegen CC.",
	["GUIDE_TIP_096"] = "Netherwalk, um Schaden zu vermeiden.",
	["GUIDE_TIP_097"] = "Siegel der Stille, um Zauberer zu stoppen.",
	["GUIDE_TIP_098"] = "Glaive Toss zum Ziehen.",
	["GUIDE_TIP_099"] = "Disintegrate ist Ihr Hauptausgabemittel für einzelne Ziele.",
	["GUIDE_TIP_100"] = "Scheiterhaufen für AoE-Gruppen.",
	["GUIDE_TIP_101"] = "Halten Sie die Abklingzeit von „Feueratem“ immer eingeschaltet (Empower-Stufe 1 reicht normalerweise aus).",
	["GUIDE_TIP_102"] = "Eternity Surge eignet sich hervorragend für mehrere Ziele.",
	["GUIDE_TIP_103"] = "Verwenden Sie Living Flame als Füllmaterial.",
	["GUIDE_TIP_104"] = "Schweben ermöglicht es Ihnen, während der Bewegung zu wirken; Benutze es oft!",
	["GUIDE_TIP_105"] = "Drachenwut ist die Abklingzeit Ihres großen Ausbruchs.",
	["GUIDE_TIP_106"] = "Obsidianschuppen zur Verteidigung.",
	["GUIDE_TIP_107"] = "Quell, um Feinde zu unterbrechen.",
	["GUIDE_TIP_108"] = "Erdrutsch, um Feinde festzuhalten.",
	["GUIDE_TIP_109"] = "Echo ist Ihr wichtigstes Combo-Tool.",
	["GUIDE_TIP_110"] = "„Traumatem“ ist eine massive Gruppenheilung (bei Bedarf verstärken).",
	["GUIDE_TIP_111"] = "Spiritbloom für Burst-Heilung bei mehreren Zielen.",
	["GUIDE_TIP_112"] = "Nutzen Sie Reversion, um die Leute auf dem Laufenden zu halten.",
	["GUIDE_TIP_113"] = "Grüne Umarmung ist eine starke gezielte Heilung.",
	["GUIDE_TIP_114"] = "„Zurückspulen“ kann eine Gruppe nach einem massiven Schadensanstieg retten.",
	["GUIDE_TIP_115"] = "Temporale Anomalie bietet jedem, den sie berührt, Schilde.",
	["GUIDE_TIP_116"] = "Dream Flight für hochmobile Heilung.",
	["GUIDE_TIP_117"] = "Smaragdblüte für günstige AoE-Heilungen.",
	["GUIDE_TIP_118"] = "Stasis zum Speichern und Wiederholen Ihrer besten Heilungen.",
	["GUIDE_TIP_119"] = "Ebon Might muss eine Verfügbarkeit von 100 % haben, um deine Verbündeten zu stärken.",
	["GUIDE_TIP_120"] = "Umbruch erweitert deine Buffs.",
	["GUIDE_TIP_121"] = "„Atem der Äonen“ ist Ihre große Unterstützungs-Abklingzeit; Passen Sie es an den Burst Ihrer Gruppe an.",
	["GUIDE_TIP_122"] = "Blasenbildende Schuppen auf dem Tank.",
	["GUIDE_TIP_123"] = "Vorausschauende Einschätzung Ihrer besten DPS-Spieler.",
	["GUIDE_TIP_124"] = "Eruption ist Ihr Hauptausgabenwert für die Verlängerung von Ebon Might.",
	["GUIDE_TIP_125"] = "Quelle der Magie für das Mana deiner Heiler.",
	["GUIDE_TIP_126"] = "„Räumliches Paradox“ hilft Heilern, während der Bewegung zu wirken.",
	["GUIDE_TIP_127"] = "Retten Sie, um Verbündete aus der Gefahrenzone zu bringen.",
	["GUIDE_TIP_128"] = "Erdrutsch zur Massenkontrolle.",
	["GUIDE_TIP_129"] = "Kill Command ist Ihr Hauptangriff; Es schickt Ihr Haustier zum Streik.",
	["GUIDE_TIP_130"] = "Verwenden Sie „Stachelschuss“, um die Abklingzeit von „Bestial Wrath“ zu verkürzen.",
	["GUIDE_TIP_131"] = "Bestial Wrath erhöht deinen Schaden und macht dein Haustier wütend.",
	["GUIDE_TIP_132"] = "Kill Shot ist Ihr Finisher für Feinde mit weniger als 20 % Gesundheit.",
	["GUIDE_TIP_133"] = "Verwenden Sie „Mehrfachschuss“, um „Kill Cleave“ für Ihr Haustier zu aktivieren.",
	["GUIDE_TIP_134"] = "Erheiterung heilt Sie und Ihr Haustier sofort.",
	["GUIDE_TIP_135"] = "Aspekt der Schildkröte blockiert jeglichen Schaden, wenn Sie in Schwierigkeiten geraten.",
	["GUIDE_TIP_136"] = "Gegenschuss unterbricht gegnerische Zauber.",
	["GUIDE_TIP_137"] = "Eine Fehlleitung Ihres Haustiers stellt eine Bedrohung für es dar.",
	["GUIDE_TIP_138"] = "„Haustier heilen“ sollte immer aktiv sein, wenn Ihr Haustier Schaden erleidet.",
	["GUIDE_TIP_139"] = "Gezielter Schuss verursacht den größten Schaden; Verschwenden Sie Ihre Ladung nicht.",
	["GUIDE_TIP_140"] = "Schnellfeuer erzeugt Fokus und verursacht schweren Schaden.",
	["GUIDE_TIP_141"] = "„Arkaner Schuss“ ist Ihre Hauptmethode, um Fokus auszugeben.",
	["GUIDE_TIP_142"] = "„Trueshot“ ist Ihre große Abklingzeit für schnelle gezielte Schüsse.",
	["GUIDE_TIP_143"] = "Multi-Shot aktiviert Trick Shots für AoE-Schaden.",
	["GUIDE_TIP_144"] = "Aspect of the Cheetah hilft Ihnen, sich schnell zu bewegen.",
	["GUIDE_TIP_145"] = "„Bindender Schuss“ hält Gruppen von Feinden an Ort und Stelle.",
	["GUIDE_TIP_146"] = "Freezing Trap schlägt einen Gegner komplett bewusstlos.",
	["GUIDE_TIP_147"] = "Benutze „Aspekt der Schildkröte“ für gefährliche Angriffe.",
	["GUIDE_TIP_148"] = "Mit „Feign Death“ können Monster dich ignorieren, wenn es zu heiß wird.",
	["GUIDE_TIP_149"] = "Kill Command generiert Fokus für deine Angriffe.",
	["GUIDE_TIP_150"] = "Eine Waldbrandbombe ist im Laufe der Zeit Ihre Hauptschadensquelle.",
	["GUIDE_TIP_151"] = "Mongoose Bite ist Ihr stärkster Angriff; Versuchen Sie, Stapel zu bilden.",
	["GUIDE_TIP_152"] = "Halten Sie „Serpent Sting“ bei starken Feinden immer aktiv.",
	["GUIDE_TIP_153"] = "Coordinated Assault stärkt die Zusammenarbeit mit Ihrem Haustier.",
	["GUIDE_TIP_154"] = "Harpune zieht dich direkt auf deinen Feind zu.",
	["GUIDE_TIP_155"] = "Fury of the Eagle ist ein mächtiger Angriff für Gruppen von Monstern.",
	["GUIDE_TIP_156"] = "Aspekt der Schildkröte für maximale Verteidigung.",
	["GUIDE_TIP_157"] = "Durch Einschüchterung kann Ihr Haustier das Ziel betäuben.",
	["GUIDE_TIP_158"] = "Lösen Sie sich, um schnell zurück zu springen und sich zu distanzieren.",
	["GUIDE_TIP_159"] = "Arcane Blast ist Ihre Basis; Je mehr Stapel, desto härter der Treffer (und desto mehr Mana).",
	["GUIDE_TIP_160"] = "Verwenden Sie Arkane Raketen nur, wenn Clearcasting für einen kostenlosen Angriff aktiv ist.",
	["GUIDE_TIP_161"] = "„Arkanes Sperrfeuer“ erschöpft deine Stapel und gibt deinem Mana etwas Ruhe.",
	["GUIDE_TIP_162"] = "Evokation ist Ihre Lebensader; Verwenden Sie es, um Ihr Mana sehr schnell wieder aufzufüllen.",
	["GUIDE_TIP_163"] = "Alter Time ist Ihr bester Freund: Es setzt Ihr Leben und Ihren Ort auf den Stand vor 10 Sekunden zurück.",
	["GUIDE_TIP_164"] = "Arcane Surge ist Ihr stärkster Angriff; Es verbraucht Ihr gesamtes Mana für massiven Schaden und regeneriert es dann schnell.",
	["GUIDE_TIP_165"] = "Mirror Image beschwört drei Kopien von dir selbst, um Feinde abzulenken und den Schaden zu verringern.",
	["GUIDE_TIP_166"] = "Langsam ist perfekt, um einen starken Feind auf Abstand zu halten, während Sie Ihre Zauber aufladen.",
	["GUIDE_TIP_167"] = "Gegenzauber stoppt feindliche Zauber; unverzichtbar in Dungeons und gegen Elite-Monster.",
	["GUIDE_TIP_168"] = "Vergessen Sie nicht die arkane Intelligenz; Dieser Buff sollte für erhöhten Schaden und Mana immer aktiv sein.",
	["GUIDE_TIP_169"] = "Halten Sie Fireball gedrückt, bis Sie einen kritischen Treffer erzielen (Heating Up).",
	["GUIDE_TIP_170"] = "Fire Blast garantiert einen kritischen Treffer; Verwenden Sie dies, um Ihren Hot Streak sofort zu aktivieren.",
	["GUIDE_TIP_171"] = "Feuern Sie Pyroblast nur ab, wenn es sofort losgeht (Hot Streak), um maximales Chaos zu erzielen.",
	["GUIDE_TIP_172"] = "Die Verbrennung ist Ihr Explosionsfenster. Dann ist alles, was einen berührt, von entscheidender Bedeutung.",
	["GUIDE_TIP_173"] = "Flamestrike ist der König von AoE; Ideal für große Gruppen.",
	["GUIDE_TIP_174"] = "Drachenatem desorientiert alle Feinde vor dir; Ideal, wenn sie zu nahe kommen.",
	["GUIDE_TIP_175"] = "Phoenix Flames gibt Ihnen einen garantierten kritischen Treffer und hilft Ihnen beim Aufbau eines Hot Streak.",
	["GUIDE_TIP_176"] = "Sie können Scorch beim Laufen verwenden; Perfekt, wenn Sie ausweichen müssen, aber trotzdem angreifen möchten.",
	["GUIDE_TIP_177"] = "Verwenden Sie Gegenzauber, um gefährliche feindliche Zauber sofort zu unterbrechen.",
	["GUIDE_TIP_178"] = "Blazing Barrier absorbiert Schaden und fügt den Angreifern etwas Feuerschaden zu.",
	["GUIDE_TIP_179"] = "Frostbolt verlangsamt Feinde, sodass sie dich niemals berühren können.",
	["GUIDE_TIP_180"] = "Sie sollten Flurry sofort wirken, sobald Brain Freeze für eine Combo aufleuchtet.",
	["GUIDE_TIP_181"] = "Eislanze verursacht dreifachen Schaden gegen gefrorene Feinde.",
	["GUIDE_TIP_182"] = "Frozen Orb erzeugt kontinuierlich Finger of Frost; perfekt für Gruppen.",
	["GUIDE_TIP_183"] = "Ice Block ist Ihr Notfallknopf; es macht dich 10 Sekunden lang unverwundbar.",
	["GUIDE_TIP_184"] = "Dein Wasserelementar kann Feinde einfrieren, was dir sofort den Effekt „Finger des Frosts“ verleiht.",
	["GUIDE_TIP_185"] = "Mit Icy Veins können Sie viel schneller wirken. Verwenden Sie dies bei großen Gruppen oder Bossen.",
	["GUIDE_TIP_186"] = "„Kältekegel“ verlangsamt alle Feinde in einem kegelförmigen Bereich vor Ihnen. nützlich für die Flucht.",
	["GUIDE_TIP_187"] = "Unterbrich Feinde mit einem Gegenzauber, um zu verhindern, dass sie dir Schaden zufügen.",
	["GUIDE_TIP_188"] = "Die Eisbarriere ist Ihr Hauptschild. Versuchen Sie, dies während der Schlachten immer aktiv zu haben.",
	["GUIDE_TIP_189"] = "Keg Smash ist Ihr Hauptbedrohungsangriff und verlangsamt Feinde.",
	["GUIDE_TIP_190"] = "Blackout Kick verringert die Abklingzeit deiner Biere; benutze es oft.",
	["GUIDE_TIP_191"] = "Feueratem verbrennt Feinde; Sie verursachen weniger Schaden, wenn sie von Keg Smash getroffen werden.",
	["GUIDE_TIP_192"] = "„Reinigendes Gebräu“ ist unerlässlich, um deine Staffelung (geringer Schaden) zu halbieren.",
	["GUIDE_TIP_193"] = "Celestial Brew gibt dir einen riesigen Schild, je nachdem, wie viel Schaden du entfernt hast.",
	["GUIDE_TIP_194"] = "Rauschender Jadewind verursacht konstanten Schaden um dich herum; gut für Gruppen geeignet.",
	["GUIDE_TIP_195"] = "Stärkendes Gebräu ist Ihr Notfallknopf für zusätzliches Leben und weniger erlittenen Schaden.",
	["GUIDE_TIP_196"] = "Schaden ausstoßen heilt dich sofort und zieht alle Heilsphären zu dir.",
	["GUIDE_TIP_197"] = "„Speerhandschlag“ unterbricht gegnerische Zauber.",
	["GUIDE_TIP_198"] = "Beinfeger betäubt alle Gegner um dich herum für ein paar Sekunden.",
	["GUIDE_TIP_199"] = "Beruhigender Nebel ist die Grundlage Ihrer Heilung; Sie können andere Zauber direkt wirken, während Sie dies kanalisieren.",
	["GUIDE_TIP_200"] = "Erneuernder Nebel breitet sich auf verwundete Verbündete aus; Verbreiten Sie dies an so viele Menschen wie möglich.",
	["GUIDE_TIP_201"] = "„Einhüllender Nebel“ sorgt im Laufe der Zeit für eine starke Heilung und verstärkt deine anderen Heilungen bei diesem Ziel.",
	["GUIDE_TIP_202"] = "„Vivify“ heilt Ihr Hauptziel und jeden, der über einen „Erneuernden Nebel“ verfügt.",
	["GUIDE_TIP_203"] = "Essence Font ist Ihre beste Option, um die gesamte Gruppe auf einmal zu heilen.",
	["GUIDE_TIP_204"] = "„Wiederbelebung“ ist eine enorme Sofortheilung für den gesamten Raid und entfernt alle negativen Effekte.",
	["GUIDE_TIP_205"] = "Life Cocoon verleiht einem Verbündeten einen großen Schild und erhöht die Heilung, die er erhält.",
	["GUIDE_TIP_206"] = "Thunder Focus Tea stärkt deinen nächsten Zauber; Verwenden Sie es mit Bedacht.",
	["GUIDE_TIP_207"] = "Verwenden Sie „Beinschwung“, um Feinde zu betäuben und den Schaden am Panzer zu verringern.",
	["GUIDE_TIP_208"] = "Eine Lähmung bringt einen Feind völlig zum Schweigen; nützlich, um einen Kampf einfacher zu machen.",
	["GUIDE_TIP_209"] = "Tigerpalme baut Chi auf; Benutze es niemals zweimal hintereinander (Meisterschaft!).",
	["GUIDE_TIP_210"] = "Blackout Kick ist eine kostengünstige Möglichkeit, Ihre Combo-Serie fortzusetzen.",
	["GUIDE_TIP_211"] = "Rising Sun Kick ist Ihr stärkster Angriff gegen ein einzelnes Ziel.",
	["GUIDE_TIP_212"] = "Fists of Fury fügt allen Feinden vor dir massiven Schaden zu; während des Gebrauchs stationär bleiben.",
	["GUIDE_TIP_213"] = "Spinning Crane Kick ist Ihr bester Angriff gegen große Monstergruppen.",
	["GUIDE_TIP_214"] = "Touch of Death tötet sofort Feinde mit weniger Leben als Sie; Nutze es bei jeder Gelegenheit.",
	["GUIDE_TIP_215"] = "„Touch of Karma“ sendet eingehenden Schaden an deinen Feind zurück; Deine beste Verteidigung.",
	["GUIDE_TIP_216"] = "Die Chi-Welle springt zwischen Verbündeten und Feinden hin und her und verursacht sowohl Schaden als auch Heilung.",
	["GUIDE_TIP_217"] = "Verwenden Sie „Spear Hand Strike“, um gefährliche Zaubersprüche von Feinden zu stoppen.",
	["GUIDE_TIP_218"] = "Flying Serpent Kick hilft dir, dich blitzschnell durch die Welt zu bewegen oder zu kämpfen.",
	["GUIDE_TIP_219"] = "Heiliger Schock ist Ihr Hauptzauber; Verwenden Sie es sowohl für schnelle Heilung als auch für Schaden.",
	["GUIDE_TIP_220"] = "Wort der Herrlichkeit ist Ihr bester Weg, heilige Kraft für sofortige Heilung einzusetzen.",
	["GUIDE_TIP_221"] = "Flash of Light ist schnell, aber teuer; Verwenden Sie es nur in Notsituationen.",
	["GUIDE_TIP_222"] = "Behalten Sie Beacon of Light immer am Tank, damit er Heilung erhält, während Sie anderen helfen.",
	["GUIDE_TIP_223"] = "Avenging Wrath (Flügel) erhöht deine Heilung und deinen Schaden erheblich; Bewahren Sie dies für schwierige Momente auf.",
	["GUIDE_TIP_224"] = "Der Hammer des Lichts eignet sich hervorragend, um eine Gruppe zu heilen, die nahe beieinander steht.",
	["GUIDE_TIP_225"] = "Göttlicher Schutz verringert den erlittenen Schaden; Vergessen Sie nicht, sich zu schützen!",
	["GUIDE_TIP_226"] = "„Hammer der Gerechtigkeit“ betäubt einen Gegner 6 Sekunden lang; Perfekt, um gefährliche Zauber zu stoppen.",
	["GUIDE_TIP_227"] = "„Segen der Freiheit“ entfernt bewegungseinschränkende Effekte von dir selbst oder einem Verbündeten.",
	["GUIDE_TIP_228"] = "„Handauflegen“ heilt ein Ziel sofort um 100 % Ihres maximalen Lebens; Ihr ultimativer Notfallknopf.",
	["GUIDE_TIP_229"] = "Der Schild der Rechtschaffenen ist Ihre Hauptverteidigung. es erhöht deine Rüstung enorm.",
	["GUIDE_TIP_230"] = "Avenger's Shield unterbricht Feinde und gibt dir einen Schild; Verwenden Sie es so schnell wie möglich.",
	["GUIDE_TIP_231"] = "Die Weihe sollte immer unter Ihren Füßen liegen, um den Schaden zusätzlich zu reduzieren.",
	["GUIDE_TIP_232"] = "Crusader Strike baut Heilige Kraft auf, die Sie für Ihren Schild oder Ihre Heilung benötigen.",
	["GUIDE_TIP_233"] = "Urteil erzeugt heilige Macht und lässt deine Feinde härter treffen.",
	["GUIDE_TIP_234"] = "Seraphim erhöht für kurze Zeit alle Ihre Sekundärstatistiken; Verwenden Sie es für zusätzliche Stärke.",
	["GUIDE_TIP_235"] = "„Guardian of Ancient Kings“ ist Ihre stärkste Verteidigung gegen massive Schläge.",
	["GUIDE_TIP_236"] = "Ardent Defender verhindert, dass Sie durch einen tödlichen Schlag sterben. eine unverzichtbare Rettung.",
	["GUIDE_TIP_237"] = "„Hand der Abrechnung“ lenkt die Aufmerksamkeit eines Monsters auf dich (Verspottung).",
	["GUIDE_TIP_238"] = "Hammer of the Righteous ist Ihr Hauptangriff gegen Gruppen von Feinden.",
	["GUIDE_TIP_239"] = "Das Urteil des Templers ist Ihr stärkster Angriff. Benutze es, sobald du 3 oder mehr Heilige Kraft hast.",
	["GUIDE_TIP_240"] = "Blade of Justice baut schnell Heilige Kraft auf; Benutze es für die Abklingzeit.",
	["GUIDE_TIP_241"] = "Urteil sorgt dafür, dass Ihr Ziel durch Ihren nächsten Angriff mit der heiligen Kraft mehr Schaden erleidet.",
	["GUIDE_TIP_242"] = "Crusader Strike ist Ihr Basisangriff, um Lücken in Ihrer Rotation zu schließen.",
	["GUIDE_TIP_243"] = "Divine Storm ist Ihre beste Waffe gegen Gruppen von Feinden. es betrifft jeden um dich herum.",
	["GUIDE_TIP_244"] = "„Hammer des Zorns“ kann nur bei Gegnern mit geringem Leben oder während „Flügel“ verwendet werden.",
	["GUIDE_TIP_245"] = "Avenging Wrath (Wings) macht alle deine Angriffe viel stärker; Verwenden Sie dies für maximalen Burst.",
	["GUIDE_TIP_246"] = "Der Schild der Rache absorbiert Schaden und explodiert dann, um den Feinden zusätzlichen Schaden zuzufügen.",
	["GUIDE_TIP_247"] = "Göttlicher Schild (Blase) macht Sie völlig unverwundbar; Ideal, um gefährliche Situationen zu überstehen.",
	["GUIDE_TIP_248"] = "„Göttliches Ross“ hilft Ihnen, sich in der Hitze des Gefechts schnell zu bewegen.",
	["GUIDE_TIP_249"] = "Sühne ist Ihr wichtigster Mechanismus; Heile Verbündete, indem du Feinden Schaden zufügst.",
	["GUIDE_TIP_250"] = "„Machtwort: Schild“ verleiht Ihrem Ziel einen sofortigen Buff und wendet „Sühne“ an.",
	["GUIDE_TIP_251"] = "Buße ist Ihr vielseitigster Zauber; Verwenden Sie es für Explosionsschaden oder sofortige Heilung.",
	["GUIDE_TIP_252"] = "Zerschmettern ist Ihr Basisangriff, um die Heilung von Sühne aktiv zu halten, ohne viel Mana zu verbrauchen.",
	["GUIDE_TIP_253"] = "Mind Blast verursacht erheblichen Schaden und verhindert einen Teil des Folgeschadens des Feindes.",
	["GUIDE_TIP_254"] = "Die Schmerzunterdrückung verringert den eingehenden Schaden erheblich. Verwenden Sie diese bei größeren Stößen am Tank.",
	["GUIDE_TIP_255"] = "Power Word: Barrier platziert eine Kuppel, die alle darin befindlichen Personen vor Schaden schützt.",
	["GUIDE_TIP_256"] = "Schisma erhöht den Schaden, den du dem Ziel zufügst, was auch deine Heilung erhöht.",
	["GUIDE_TIP_257"] = "Purify entfernt schädliche magische Effekte und Krankheiten von deinen Verbündeten.",
	["GUIDE_TIP_258"] = "Leap of Faith lockt einen Verbündeten zu Ihnen; Perfekt, um Menschen vor Bränden zu retten.",
	["GUIDE_TIP_259"] = "Flash Heal ist Ihre schnelle Notfallheilung für individuelle Ziele.",
	["GUIDE_TIP_260"] = "„Heiliges Wort: Gelassenheit“ ist eine gewaltige Sofortheilung mit einer langen Abklingzeit, die durch „Blitzheilung“ verkürzt wird.",
	["GUIDE_TIP_261"] = "„Heiliges Wort: Heiligung“ ist die beste Option, um eine Gruppe in unmittelbarer Nähe zu heilen.",
	["GUIDE_TIP_262"] = "Erneuerung sorgt im Laufe der Zeit für Heilung; Halten Sie dies für den Panzer oder Spieler, die ständig Schaden erleiden, aktiv.",
	["GUIDE_TIP_263"] = "Gebet der Besserung springt auf andere Verbündete über, wenn das Ziel Schaden erleidet.",
	["GUIDE_TIP_264"] = "„Göttliche Hymne“ ist ein mächtiger Kanalisierungszauber, der die gesamte Gruppe heilt und ihre erhaltene Heilung erhöht.",
	["GUIDE_TIP_265"] = "Schutzgeist erhöht die erhaltene Heilung und verhindert, dass das Ziel stirbt.",
	["GUIDE_TIP_266"] = "Kraftinfusion erhöht Ihr Tempo erheblich; Sie können dies auch auf einen starken DPS-Spieler übertragen.",
	["GUIDE_TIP_267"] = "„Fade“ führt dazu, dass Monster dich vorübergehend ignorieren, wenn du zu viel Bedrohung aufgebaut hast.",
	["GUIDE_TIP_268"] = "Symbol der Hoffnung stellt einen Teil des Manas aller Heiler in Ihrer Gruppe wieder her.",
	["GUIDE_TIP_269"] = "Schattenwort: Der Schmerz muss bei all deinen Feinden immer aktiv bleiben.",
	["GUIDE_TIP_270"] = "„Vampirberührung“ verursacht mit der Zeit Schaden und stellt einen Teil Ihres eigenen Lebens wieder her.",
	["GUIDE_TIP_271"] = "Mind Blast erzeugt Wahnsinn und verursacht erheblichen direkten Schaden.",
	["GUIDE_TIP_272"] = "Mind Flay ist Ihr Füllzauber, der den Feind verlangsamt, während Sie auf Ihre anderen Abklingzeiten warten.",
	["GUIDE_TIP_273"] = "Sie können Void Bolt nur während Voidform verwenden; es erfrischt die Dauer Ihrer Krankheiten.",
	["GUIDE_TIP_274"] = "„Schattenwort: Tod“ ist Ihr Finisher für Feinde, die dem Tod nahe sind.",
	["GUIDE_TIP_275"] = "„Shadow Crash“ eignet sich perfekt, um Gruppen von Feinden „Vampirberührung“ zu verleihen.",
	["GUIDE_TIP_276"] = "Streuung reduziert den gesamten eingehenden Schaden um 75 %; Dein bester Weg, um zu überleben.",
	["GUIDE_TIP_277"] = "Shadowfiend beschwört eine Kreatur, die deinen Feind angreift und bei dir Wahnsinn erzeugt.",
	["GUIDE_TIP_278"] = "Vampirische Umarmung wandelt einen Teil Ihres Schadens in Heilung für die Gruppe um.",
	["GUIDE_TIP_279"] = "Garrote ist Ihr Anfang; es wendet Blutung an und generiert Combo-Punkte.",
	["GUIDE_TIP_280"] = "Der Bruch ist Ihr wichtigster Abschluss; Halten Sie diese Blutung bei Ihrem Ziel immer aktiv.",
	["GUIDE_TIP_281"] = "Backstab ist Ihr Basisbauer für Combo-Punkte, wenn Sie sich hinter dem Ziel befinden.",
	["GUIDE_TIP_282"] = "Dispatch ist Ihr mächtiger Finisher, wenn der Feind nur noch wenige Lebenspunkte hat.",
	["GUIDE_TIP_283"] = "Vendetta markiert deinen Feind und fügt ihm zusätzlichen Schaden zu. Verwenden Sie dies für Burst.",
	["GUIDE_TIP_284"] = "„Vanish“ lässt Sie mitten im Kampf verschwinden. nützlich zum Entkommen oder Wiederöffnen.",
	["GUIDE_TIP_285"] = "Tritt unterbricht gegnerische Zauber; wichtig, um Schäden vorzubeugen.",
	["GUIDE_TIP_286"] = "Mit Shadowstep können Sie direkt hinter Ihrem Ziel erscheinen.",
	["GUIDE_TIP_287"] = "Ausweichen erhöht Ihre Ausweichchance erheblich, wenn Sie physische Treffer einstecken.",
	["GUIDE_TIP_288"] = "„Umhang der Schatten“ macht Sie immun gegen Magie und entfernt schädliche Effekte.",
	["GUIDE_TIP_289"] = "Sinister Strike ist Ihr Hauptangriff, um Combo-Punkte zu sammeln.",
	["GUIDE_TIP_290"] = "„Roll the Bones“ gibt dir zufällige Kampfboni; Halten Sie dies immer aktiv.",
	["GUIDE_TIP_291"] = "Eviscerate ist Ihr Standard-Finisher mit hohem Schaden.",
	["GUIDE_TIP_292"] = "Verwenden Sie Pistolenschuss, wenn „Gelegenheit“ aufleuchtet, um kostenlose Combo-Punkte zu erhalten.",
	["GUIDE_TIP_293"] = "Blade Flurry sorgt dafür, dass Ihre Angriffe alle Feinde in der Nähe treffen. Ideal für Gruppen.",
	["GUIDE_TIP_294"] = "Adrenaline Rush erhöht Ihre Energieerzeugung und Angriffsgeschwindigkeit erheblich.",
	["GUIDE_TIP_295"] = "Blind verwirrt einen Feind für eine Minute; Perfekt für die Massenkontrolle.",
	["GUIDE_TIP_296"] = "Vanish ist Ihr Notfallknopf, um gefährlichen Situationen zu entkommen.",
	["GUIDE_TIP_297"] = "Treten Sie diese nervigen Zauberer, um ihre Zauber zu stoppen.",
	["GUIDE_TIP_298"] = "Finte verringert den Schaden, den Sie durch Flächenangriffe (AoE) erleiden.",
	["GUIDE_TIP_299"] = "Shadowstrike ist Ihr stärkster Opener und Combo Point Builder aus Stealth oder Shadow Dance.",
	["GUIDE_TIP_300"] = "Ausweiden ist Ihr primärer Finisher für maximalen Schaden.",
	["GUIDE_TIP_301"] = "Schwarzpulver ist Ihr Finisher für Gruppen von Feinden.",
	["GUIDE_TIP_302"] = "Mit Shadow Dance können Sie Stealth-Angriffe ausführen, ohne unsichtbar zu sein.",
	["GUIDE_TIP_303"] = "Shadow Blades sorgt dafür, dass Ihre Angriffe zusätzlichen Schaden anrichten und mehr Combo-Punkte generieren.",
	["GUIDE_TIP_304"] = "Shuriken Tornado ist perfekt, um eine ganze Gruppe von Feinden gleichzeitig mit Krankheiten zu infizieren.",
	["GUIDE_TIP_305"] = "„Vanish“ setzt Ihre Tarnfähigkeiten mitten im Kampf zurück.",
	["GUIDE_TIP_306"] = "Tritt ist wichtig, um Feinde zu unterbrechen.",
	["GUIDE_TIP_307"] = "„Nierenschuss“ betäubt (betäubt) einen Feind basierend auf Ihren Combo-Punkten.",
	["GUIDE_TIP_308"] = "Cloak of Shadows schützt Sie vor allen magischen Angriffen.",
	["GUIDE_TIP_309"] = "Lightning Bolt ist Ihr Basisangriff, um Mahlstrom aufzubauen.",
	["GUIDE_TIP_310"] = "Chain Lightning ist Ihre beste Waffe gegen Gruppen von Feinden.",
	["GUIDE_TIP_311"] = "Earth Shock ist Ihr mächtiger Finisher; Verwenden Sie es, wenn Ihr Mahlstrom fast voll ist.",
	["GUIDE_TIP_312"] = "Lava Burst verursacht garantiert kritischen Schaden, wenn Flame Shock auf das Ziel trifft.",
	["GUIDE_TIP_313"] = "Halten Sie den Flammenschock bei Ihren Feinden immer aktiv, um konstanten Schaden zu verursachen.",
	["GUIDE_TIP_314"] = "Feuerelementar erhöht den Schaden Ihres Lavastoßes und erzeugt Mahlstrom.",
	["GUIDE_TIP_315"] = "„Astralverschiebung“ verringert den eingehenden Schaden um 40 %; Ihre Hauptverteidigung.",
	["GUIDE_TIP_316"] = "Windscherung ist die beste Unterbrechung im Spiel; Benutze es oft!",
	["GUIDE_TIP_317"] = "Das Kondensatortotem betäubt alle Feinde in der Nähe nach 2 Sekunden.",
	["GUIDE_TIP_318"] = "Blutrausch (oder Heldentum) erhöht die Angriffsgeschwindigkeit der gesamten Gruppe erheblich.",
	["GUIDE_TIP_319"] = "Sturmschlag ist Ihr Hauptangriff; Verwenden Sie es, sobald es verfügbar ist.",
	["GUIDE_TIP_320"] = "Rockbiter erzeugt Mahlstrom und verstärkt deine nächsten Angriffe.",
	["GUIDE_TIP_321"] = "„Lavapeitsche“ ist Ihr sekundärer Angriff, mit dem Sie „Mahlstrom“ einsetzen können.",
	["GUIDE_TIP_322"] = "Verwenden Sie Crash Lightning gegen Gruppen, um auch Ihre anderen Angriffe AoE zu machen.",
	["GUIDE_TIP_323"] = "Flammenschock sollte immer auf Ihrem Ziel sein, um mit der Zeit zusätzlichen Schaden zu verursachen.",
	["GUIDE_TIP_324"] = "Wilder Geist beschwört zwei Wölfe, die Schaden verursachen und Mahlstrom für dich erzeugen.",
	["GUIDE_TIP_325"] = "Vergessen Sie Astral Shift nicht für schwere Treffer. es rettet dein Leben.",
	["GUIDE_TIP_326"] = "Windscherung, um gegnerische Zauberer sofort zum Schweigen zu bringen.",
	["GUIDE_TIP_327"] = "Verwenden Sie das Kondensatortotem, um in großen Gruppen Luft zum Atmen zu gewinnen.",
	["GUIDE_TIP_328"] = "Ghost Wolf hilft Ihnen, schnell voranzukommen und Verzögerungen zu ignorieren.",
	["GUIDE_TIP_329"] = "Riptide sorgt für eine sofortige Heilung und eine starke Heilung im Laufe der Zeit.",
	["GUIDE_TIP_330"] = "Chain Heal ist der König der Gruppenheilung; es springt zu verletzten Verbündeten.",
	["GUIDE_TIP_331"] = "Healing Wave ist langsam, aber effizient; Verwenden Sie dies, wenn der Schaden gering ist.",
	["GUIDE_TIP_332"] = "Healing Surge ist Ihre schnelle Notfallheilung für kritische Situationen.",
	["GUIDE_TIP_333"] = "Das Healing Stream Totem bietet der Gruppe passive Heilung, während Sie andere Dinge tun.",
	["GUIDE_TIP_334"] = "Das Totem der Geisterverbindung gleicht das Leben aller Menschen in der Nähe aus. ein echter Lebensretter.",
	["GUIDE_TIP_335"] = "Nutzen Sie Astral Shift, um selbst weniger Schaden zu erleiden und gleichzeitig andere zu heilen.",
	["GUIDE_TIP_336"] = "Als Heiler ist Wind Shear auch Ihr Job; Hör auf mit diesen Zaubersprüchen!",
	["GUIDE_TIP_337"] = "Elementarbeherrschung erhöht Ihr Tempo erheblich und sorgt so für eine schnellere Heilung.",
	["GUIDE_TIP_338"] = "„Totem der heilenden Flut“ ist die stärkste Abklingzeit für die Gruppenheilung. Bewahren Sie dies für größeren AOE-Schaden auf.",
	["GUIDE_TIP_339"] = "Agony sollte immer Ihr Ziel sein; Es verursacht immer mehr Schaden, je länger es tickt.",
	["GUIDE_TIP_340"] = "Korruption ist Ihr grundlegender Fluch für konstanten Schaden im Laufe der Zeit.",
	["GUIDE_TIP_341"] = "Instabiles Gebrechen ist Ihr stärkster Fluch; Es kann jeweils nur eins aktiv sein.",
	["GUIDE_TIP_342"] = "Vile Taint ist perfekt, um eine ganze Gruppe von Feinden auf einmal mit Agony zu infizieren.",
	["GUIDE_TIP_343"] = "Malefic Rapture fügt jedem, der deine Flüche trägt, massiven Schaden zu.",
	["GUIDE_TIP_344"] = "Shadow Bolt ist Ihr Füllzauber zum Aufbau von Seelensplittern.",
	["GUIDE_TIP_345"] = "Halten Sie die Abklingzeit Ihrer Seelenfäule bereit, um mehreren Zielen zusätzlichen Schaden zuzufügen.",
	["GUIDE_TIP_346"] = "Seelenfeuer verursacht erheblichen Schaden und gibt dir sofort einen Seelensplitter.",
	["GUIDE_TIP_347"] = "Mit Demonic Circle können Sie sich sofort an einen sicheren Ort zurückteleportieren.",
	["GUIDE_TIP_348"] = "Vergessen Sie nicht, Ihren Gesundheitsstein herzustellen. Es ist Ihr eigener kostenloser „Trank“.",
	["GUIDE_TIP_349"] = "Hand von Gul'dan verbraucht deine Seelensplitter, um wilde Kobolde zu beschwören.",
	["GUIDE_TIP_350"] = "„Schreckenspirscher rufen“ sollte sofort eingesetzt werden, sobald die Abklingzeit abgelaufen ist.",
	["GUIDE_TIP_351"] = "Demonbolt erzeugt 2 Seelensplitter; Verwenden Sie es, wenn „Demonic Core“ aufleuchtet.",
	["GUIDE_TIP_352"] = "„Dämonischen Tyrannen beschwören“ erhöht die Dauer aller Ihrer aktiven Dämonen und macht sie stärker.",
	["GUIDE_TIP_353"] = "Durch die Implosion explodieren alle Ihre Kobolde und fügen Gruppen von Feinden massiven Schaden zu.",
	["GUIDE_TIP_354"] = "Shadow Bolt ist Ihre grundlegende Möglichkeit, Seelensplitter zu sammeln.",
	["GUIDE_TIP_355"] = "Mit „Dämonische Stärke“ kann Ihr Teufelswächter mächtige Runden zählen.",
	["GUIDE_TIP_356"] = "Grimoire: Teufelswache beschwört eine zweite Wache für zusätzlichen Schaden und eine Betäubung.",
	["GUIDE_TIP_357"] = "„Unendliche Entschlossenheit“ reduziert eingehenden Schaden und verhindert, dass deine Zauber unterbrochen werden.",
	["GUIDE_TIP_358"] = "Halten Sie Ihren Voidwalker beim Leveln aktiv, damit er alle Treffer einstecken kann.",
	["GUIDE_TIP_359"] = "Chaos Bolt ist Ihr stärkster Angriff; Benutze es, um deine Seelensplitterfragmente abzuladen.",
	["GUIDE_TIP_360"] = "Einäschern ist Ihr Füllmaterial zum Aufbau von Seelensplitterfragmenten.",
	["GUIDE_TIP_361"] = "Feuersbrunst wirkt augenblicklich und verleiht Ihnen „Rückzug“, wodurch Ihre nachfolgenden Zauber schneller ausgeführt werden.",
	["GUIDE_TIP_362"] = "„Feuerbrand“ sollte immer auf deinen Feind brennen und ihm konstanten Schaden und zusätzliche Fragmente verursachen.",
	["GUIDE_TIP_363"] = "„Infernal beschwören“ ist deine große Abklingzeit; Es regnet Feuer und lähmt Feinde beim Aufprall.",
	["GUIDE_TIP_364"] = "Feuerregen ist Ihre beste Waffe gegen große Gruppen von Feinden.",
	["GUIDE_TIP_365"] = "Shadowburn ist perfekt, um Feinde mit wenig Leben schnell zu töten.",
	["GUIDE_TIP_366"] = "Mit Havoc können Ihre Zauber auch ein zweites Ziel treffen. wesentlich für „Spaltungs“-Schäden.",
	["GUIDE_TIP_367"] = "Mit „Command Demon“ können Sie die Spezialfähigkeit Ihres aktiven Dämons nutzen.",
	["GUIDE_TIP_368"] = "Nutzen Sie Unendliche Entschlossenheit, wenn Sie wissen, dass ein schwerer Schlag bevorsteht.",
	["GUIDE_TIP_369"] = "„Mortal Strike“ ist Ihr härtester Schlag; Benutze es so schnell wie möglich, um Wut auszugeben.",
	["GUIDE_TIP_370"] = "Überwältigung kann nicht ausgewichen werden und verstärkt Ihren nächsten tödlichen Schlag.",
	["GUIDE_TIP_371"] = "Colossus Smash durchbricht die Rüstung Ihres Feindes und verursacht massiven Schaden.",
	["GUIDE_TIP_372"] = "„Ausführen“ ist Ihr tödlicher Finisher für Feinde mit weniger als 20 % Gesundheit.",
	["GUIDE_TIP_373"] = "Bladestorm verwandelt Sie in einen Wirbelsturm aus Stahl; Ideal für Gruppen von Feinden.",
	["GUIDE_TIP_374"] = "„Slam“ ist Ihr Füllangriff, wenn Sie zu viel Wut haben und andere Angriffe in der Abklingzeit sind.",
	["GUIDE_TIP_375"] = "„Stirb durch das Schwert“ ist deine beste Verteidigung. es blockiert fast alle physischen Angriffe.",
	["GUIDE_TIP_376"] = "Pummel unterbricht feindliche Zauber; Lass diese Zauberer nicht wirken!",
	["GUIDE_TIP_377"] = "Storm Bolt lähmt (betäubt) einen Feind aus der Ferne; nützlich, um Gefahren zu stoppen.",
	["GUIDE_TIP_378"] = "„Angreifen“ ist der beste Weg, den Kampf sofort zu eröffnen und Wut aufzubauen.",
	["GUIDE_TIP_379"] = "Rampage ist Ihr Hauptangriff; Es macht dich „wütend“ für zusätzliche Geschwindigkeit und Schaden.",
	["GUIDE_TIP_380"] = "Blutdurst heilt dich ein wenig und ist dein wichtigster Erbauer von Wut.",
	["GUIDE_TIP_381"] = "Wütender Schlag verursacht erheblichen Schaden und kann oft zweimal hintereinander eingesetzt werden.",
	["GUIDE_TIP_382"] = "„Ausführen“ baut eine Menge Wut auf und fügt schwachen Feinden schweren Schaden zu.",
	["GUIDE_TIP_383"] = "Rücksichtslosigkeit ist Ihre große Abklingzeit; Du erhältst 100 % mehr Wut und viele weitere kritische Treffer.",
	["GUIDE_TIP_384"] = "„Wirbelwind“ sorgt dafür, dass Ihre nächsten 2 Angriffe mehrere Feinde treffen. Unverzichtbar für AoE.",
	["GUIDE_TIP_385"] = "Wütende Regeneration heilt Sie enorm, solange Sie Blutdurst verwenden.",
	["GUIDE_TIP_386"] = "Benutze Pummel, um diese lästigen feindlichen Zaubersprüche sofort zu stoppen.",
	["GUIDE_TIP_387"] = "„Durchdringendes Heulen“ verlangsamt alle Feinde um dich herum; nützlich für die Kontrolle.",
	["GUIDE_TIP_388"] = "Mit Heroic Leap können Sie große Entfernungen überbrücken; Perfekt für Mobilität.",
	["GUIDE_TIP_389"] = "Shield Slam ist Ihr stärkster Bedrohungsangriff und erzeugt viel Wut.",
	["GUIDE_TIP_390"] = "„Donnerschlag“ verlangsamt Feinde und hält Gruppen von Monstern von dir fern.",
	["GUIDE_TIP_391"] = "Rache schlägt nach einem Block oder Ausweichen hart zurück; Kostenloser Schaden gegen Gruppen.",
	["GUIDE_TIP_392"] = "Der Schildblock sollte immer aktiv sein, wenn physische Treffer von Monstern einstecken.",
	["GUIDE_TIP_393"] = "„Schmerz ignorieren“ absorbiert einen großen Teil des eingehenden Schadens; Benutze dafür deine Wut.",
	["GUIDE_TIP_394"] = "Avatar verwandelt dich in einen Riesen; Sie richten mehr Schaden an und entkommen Verzögerungen.",
	["GUIDE_TIP_395"] = "Der Schildwall ist Ihre stärkste Verteidigung. Verwenden Sie dies, wenn wirklich etwas schiefzugehen droht.",
	["GUIDE_TIP_396"] = "„Letztes Gefecht“ erhöht vorübergehend Ihr maximales Leben; Ihr ultimativer Notfallknopf.",
	["GUIDE_TIP_397"] = "Pummel ist unerlässlich, um Zauberer zu dir zu zwingen, indem du ihre Zauber stoppst.",
	["GUIDE_TIP_398"] = "„Abfangen“ (oder „Angreifen“) hilft Ihnen, schnell zu Feinden oder Verbündeten zu gelangen.",
})

merge(ns._mhLocales and ns._mhLocales.frFR, {
	["GUIDE_TIP_001"] = "Gardez toujours Moonfire et Sunfire actifs sur votre cible pour infliger des dégâts au fil du temps.",
	["GUIDE_TIP_002"] = "Utilisez Wrath pour activer Solar Eclipse et augmenter vos dégâts naturels.",
	["GUIDE_TIP_003"] = "Utilisez Starfire pendant l'éclipse lunaire pour frapper plusieurs ennemis à la fois.",
	["GUIDE_TIP_004"] = "Starsurge est votre attaque la plus puissante ; utilisez-le une fois que vous avez suffisamment de puissance astrale.",
	["GUIDE_TIP_005"] = "Starfall est parfait pour les groupes de monstres ; ça touche tout à proximité.",
	["GUIDE_TIP_006"] = "N'oubliez pas Barkskin lorsque vous êtes attaqué ; cela réduit les dégâts.",
	["GUIDE_TIP_007"] = "Typhoon est utile pour chasser les ennemis s'ils s'approchent trop près.",
	["GUIDE_TIP_008"] = "Apaiser supprime la colère (Enrage) des monstres ; très utile dans les donjons.",
	["GUIDE_TIP_009"] = "Dash vous aide à vous échapper rapidement ou à courir plus rapidement vers votre prochain objectif.",
	["GUIDE_TIP_010"] = "Restez toujours sous forme Moonkin pour plus de dégâts et une armure supplémentaire.",
	["GUIDE_TIP_011"] = "Commencez les batailles avec Rake from Prowl pour des dégâts et des saignements supplémentaires.",
	["GUIDE_TIP_012"] = "Rip est votre finisseur principal ; gardez toujours ce saignement actif sur les ennemis puissants.",
	["GUIDE_TIP_013"] = "Utilisez Ferocious Bite comme finisseur si votre ennemi est presque mort ou si votre Rip est déjà actif.",
	["GUIDE_TIP_014"] = "Shred est votre attaque principale pour accumuler des points de combo.",
	["GUIDE_TIP_015"] = "Tiger's Fury vous donne instantanément de l'énergie et augmente vos dégâts ; utilisez-le souvent !",
	["GUIDE_TIP_016"] = "Thrash frappe tous les ennemis autour de vous et les fait saigner ; bon pour les groupes.",
	["GUIDE_TIP_017"] = "Les instincts de survie sont votre meilleure défense ; utilisez-le en cas de dangers majeurs.",
	["GUIDE_TIP_018"] = "Skull Bash interrompt les sorts ennemis et vous emmène directement vers votre cible.",
	["GUIDE_TIP_019"] = "Mutiler peut étourdir un ennemi si vous souhaitez le geler un instant.",
	["GUIDE_TIP_020"] = "Predatory Swiftness garantit que vous pouvez parfois utiliser Regrowth immédiatement et gratuitement.",
	["GUIDE_TIP_021"] = "Utilisez Moonfire pour tirer de loin – plus sûr que de sauter au visage.",
	["GUIDE_TIP_022"] = "Bear Form est la forme de votre tank pendant la mise à niveau – restez-y si vous prenez un coup.",
	["GUIDE_TIP_023"] = "Ironfur atténue les coups physiques – rappelez-vous-en contre les élites et les rares.",
	["GUIDE_TIP_024"] = "Growl aide si un autre joueur prend accidentellement une menace.",
	["GUIDE_TIP_025"] = "Écrasez plusieurs ennemis ; gardez-le actif pour la menace AOE.",
	["GUIDE_TIP_026"] = "Mangle est un élément de base important – utilisez-le souvent.",
	["GUIDE_TIP_027"] = "Barkskin est pour les moments « oups » – ne le gardez pas trop longtemps jusqu'à ce que vous soyez presque mort.",
	["GUIDE_TIP_028"] = "Régénération frénétique : guérissez à temps, pas à la dernière minute.",
	["GUIDE_TIP_029"] = "Gardez Mark of the Wild actif ; ce buff gratuit donne des statistiques supplémentaires et rend chaque tirage un peu plus sûr.",
	["GUIDE_TIP_030"] = "Skull Bash interrompt les lancers ennemis - apprenez à le préparer dans les donjons.",
	["GUIDE_TIP_031"] = "Gardez toujours le rajeunissement actif sur le réservoir pour une guérison constante.",
	["GUIDE_TIP_032"] = "Lifebloom doit toujours être sur le réservoir ; cela donne un gros soin quand il expire.",
	["GUIDE_TIP_033"] = "Utilisez Wild Growth si tout le groupe subit des dégâts.",
	["GUIDE_TIP_034"] = "La repousse est votre guérison rapide en cas d’urgence.",
	["GUIDE_TIP_035"] = "Swiftmend donne un gros soin immédiat, mais vous devez d'abord avoir Rejuvenation sur la cible.",
	["GUIDE_TIP_036"] = "Placez l'Efflorescence (le cercle) là où se trouvent la plupart des gens.",
	["GUIDE_TIP_037"] = "Utilisez Moonfire et Sunfire pour réduire les dégâts si personne ne meurt.",
	["GUIDE_TIP_038"] = "Ironbark réduit les dégâts subis par le char; utilisez-le pour les gros succès.",
	["GUIDE_TIP_039"] = "Utilisez Innervate sur vous-même si vous manquez de mana et avez besoin de beaucoup de soins.",
	["GUIDE_TIP_040"] = "Nature's Swiftness rend votre prochaine repousse gratuite et instantanée.",
	["GUIDE_TIP_041"] = "Death Strike est votre bouton le plus important ; il vous soigne et vous donne un bouclier après des dégâts.",
	["GUIDE_TIP_042"] = "Marrowrend construit Bone Shield. Gardez toujours cela au-dessus de 5 piles pour une armure supplémentaire.",
	["GUIDE_TIP_043"] = "Heart Strike est votre attaque de remplissage pour développer la puissance runique, en particulier dans Death and Decay.",
	["GUIDE_TIP_044"] = "Livrez Mort et Dégradation à des groupes d'ennemis afin que votre Heart Strike atteigne plusieurs cibles.",
	["GUIDE_TIP_045"] = "Blood Boil propage vos maladies et aide à retenir l'attention de tous les monstres.",
	["GUIDE_TIP_046"] = "Dancing Rune Weapon est une défense solide qui vous aide à parer les attaques.",
	["GUIDE_TIP_047"] = "Vampiric Blood vous donne temporairement beaucoup plus de vie ; utilisez-le si vous êtes en danger.",
	["GUIDE_TIP_048"] = "Anti-Magic Shell bloque les dégâts magiques et vous évite de subir des effets indésirables.",
	["GUIDE_TIP_049"] = "Asphyxier paralyse un ennemi pendant quelques secondes ; utile pour arrêter les sorts dangereux.",
	["GUIDE_TIP_050"] = "Death Grip attire instantanément un ennemi vers vous. Parfait pour récupérer les évadés.",
	["GUIDE_TIP_051"] = "Frost Strike est votre principal moyen de dépenser de la puissance runique.",
	["GUIDE_TIP_052"] = "Howling Blast applique Frost Fever. Utilisez-le toujours lorsque le processus Rime s'allume.",
	["GUIDE_TIP_053"] = "L'effacement est votre attaque principale. Utilisez-le lorsque vous avez des déclenchements de Killing Machine pour des dégâts critiques.",
	["GUIDE_TIP_054"] = "Remordsless Winter fait des dégâts constants autour de vous ; idéal pour les groupes de monstres.",
	["GUIDE_TIP_055"] = "Pilier de Givre augmente considérablement votre Force ; utilisez-le dans chaque bataille majeure.",
	["GUIDE_TIP_056"] = "Empower Rune Weapon vous redonne instantanément des runes et de la puissance runique pour une rafale supplémentaire.",
	["GUIDE_TIP_057"] = "Chains of Ice ralentit considérablement les ennemis ; utile pour garder une distance ou arrêter quelqu'un.",
	["GUIDE_TIP_058"] = "Mind Freeze est votre « coup de pied » pour interrompre les sorts ennemis.",
	["GUIDE_TIP_059"] = "N'oubliez pas Death Strike si votre vie est faible ; cela coûte de la puissance runique mais vous sauve la vie.",
	["GUIDE_TIP_060"] = "L'épidémie infecte instantanément tous les ennemis avec la peste virulente. Commencez chaque bataille avec ça.",
	["GUIDE_TIP_061"] = "Frappe purulente applique des blessures purulentes à votre cible.",
	["GUIDE_TIP_062"] = "Scourge Strike fait exploser les blessures purulentes et inflige des dégâts importants.",
	["GUIDE_TIP_063"] = "Death Coil est votre dépensier pour la puissance runique ; cela donne du pouvoir à votre goule.",
	["GUIDE_TIP_064"] = "Apocalypse invoque des armées de morts-vivants en faisant exploser des blessures purulentes. Utilisez-le pour le burst.",
	["GUIDE_TIP_065"] = "Dark Transformation transforme votre goule en une bête monstrueuse dotée de nouveaux pouvoirs.",
	["GUIDE_TIP_066"] = "L'Armée des Morts invoque une armée massive ; gardez cela pour les patrons les plus coriaces.",
	["GUIDE_TIP_067"] = "Combattez dans votre Mort et Dégradation pour que votre Frappe du Fléau frappe plusieurs ennemis à la fois.",
	["GUIDE_TIP_068"] = "Anti-Magic Shell est essentiel pour annuler les sorts magiques pendant les combats.",
	["GUIDE_TIP_069"] = "Chaos Strike est votre principal dépensier.",
	["GUIDE_TIP_070"] = "Utilisez Blade Dance pendant le temps de recharge pour AoE.",
	["GUIDE_TIP_071"] = "Eye Beam vous donne la métamorphose ; utilisez-le souvent.",
	["GUIDE_TIP_072"] = "Fel Rush pour le mouvement et les dégâts.",
	["GUIDE_TIP_073"] = "Le flou est votre meilleure défense.",
	["GUIDE_TIP_074"] = "Retraite vengeresse pour gagner de la Fureur.",
	["GUIDE_TIP_075"] = "Métamorphose pour grand éclat.",
	["GUIDE_TIP_076"] = "Aura d'immolation pour AoE passive.",
	["GUIDE_TIP_077"] = "Interrompre pour interrompre les lancers.",
	["GUIDE_TIP_078"] = "Consommez de la magie pour dissiper les ennemis.",
	["GUIDE_TIP_079"] = "Soul Carver pour de gros dégâts/guérisons.",
	["GUIDE_TIP_080"] = "Demon Spikes doit être actif lorsqu’il subit des coups physiques.",
	["GUIDE_TIP_081"] = "L'Aura d'Immolation génère de la Fureur.",
	["GUIDE_TIP_082"] = "Fel Devastation est votre soin \"oh-sh*t\".",
	["GUIDE_TIP_083"] = "Sceau de flamme pour pull/AoE.",
	["GUIDE_TIP_084"] = "Frappe Infernale pour la mobilité.",
	["GUIDE_TIP_085"] = "Les piles de fragilité vous aident à survivre.",
	["GUIDE_TIP_086"] = "Sceau du silence pour les lanceurs de sorts.",
	["GUIDE_TIP_087"] = "Métamorphose pour un maximum de HP.",
	["GUIDE_TIP_088"] = "Lancez Glaive pour récupérer les ajouts.",
	["GUIDE_TIP_089"] = "Void Bolt est votre principal sort de dégâts.",
	["GUIDE_TIP_090"] = "Utilisez Consommateur d'Âmes pour soigner.",
	["GUIDE_TIP_091"] = "Larme d'essence pour les dégâts de zone.",
	["GUIDE_TIP_092"] = "La Métamorphose du Vide est votre grande explosion.",
	["GUIDE_TIP_093"] = "Chaos Nova pour l'étourdissement.",
	["GUIDE_TIP_094"] = "Spectral Sight pour trouver les ennemis cachés.",
	["GUIDE_TIP_095"] = "Emprisonnement pour CC.",
	["GUIDE_TIP_096"] = "Netherwalk pour éviter les dégâts.",
	["GUIDE_TIP_097"] = "Sceau du silence pour arrêter les lanceurs de sorts.",
	["GUIDE_TIP_098"] = "Glaive Toss pour tirer.",
	["GUIDE_TIP_099"] = "La désintégration est votre principale dépense pour des cibles uniques.",
	["GUIDE_TIP_100"] = "Bûcher pour les groupes AoE.",
	["GUIDE_TIP_101"] = "Gardez toujours Fire Breath en temps de recharge (le niveau d'empowerment 1 est généralement suffisant).",
	["GUIDE_TIP_102"] = "Eternity Surge est idéal pour plusieurs cibles.",
	["GUIDE_TIP_103"] = "Utilisez Living Flame comme remplissage.",
	["GUIDE_TIP_104"] = "Le survol vous permet de lancer un sort tout en vous déplaçant ; utilisez-le souvent !",
	["GUIDE_TIP_105"] = "Dragonrage est votre temps de recharge de grande rafale.",
	["GUIDE_TIP_106"] = "Écailles d'obsidienne pour la défense.",
	["GUIDE_TIP_107"] = "Quell pour interrompre les ennemis.",
	["GUIDE_TIP_108"] = "Glissement de terrain pour enraciner les ennemis sur place.",
	["GUIDE_TIP_109"] = "Echo est votre outil combo le plus important.",
	["GUIDE_TIP_110"] = "Dream Breath est un soin de groupe massif (renforcement si nécessaire).",
	["GUIDE_TIP_111"] = "Spiritbloom pour des soins éclatés sur plusieurs cibles.",
	["GUIDE_TIP_112"] = "Utilisez Reversion pour garder les gens au courant.",
	["GUIDE_TIP_113"] = "Verdant Embrace est un puissant soin ciblé.",
	["GUIDE_TIP_114"] = "Rewind peut sauver un groupe après un pic de dégâts massif.",
	["GUIDE_TIP_115"] = "L'Anomalie Temporelle fournit des boucliers à tous ceux qu'elle touche.",
	["GUIDE_TIP_116"] = "Dream Flight pour une guérison à haute mobilité.",
	["GUIDE_TIP_117"] = "Fleur d'émeraude pour des soins AoE bon marché.",
	["GUIDE_TIP_118"] = "Stasis pour stocker et répéter vos meilleurs soins.",
	["GUIDE_TIP_119"] = "Ebon Might doit avoir une disponibilité de 100 % pour améliorer vos alliés.",
	["GUIDE_TIP_120"] = "Le bouleversement étend vos buffs.",
	["GUIDE_TIP_121"] = "Breath of Eons est votre gros temps de recharge de support ; chronométrez-le avec le burst de votre groupe.",
	["GUIDE_TIP_122"] = "Des écailles boursouflées sur le réservoir.",
	["GUIDE_TIP_123"] = "Prescience sur vos meilleurs joueurs DPS.",
	["GUIDE_TIP_124"] = "Eruption est votre principale dépense pour étendre Ebon Might.",
	["GUIDE_TIP_125"] = "Source de magie pour le mana de vos guérisseurs.",
	["GUIDE_TIP_126"] = "Spatial Paradox aide les guérisseurs à lancer des sorts tout en se déplaçant.",
	["GUIDE_TIP_127"] = "Sauvetage pour mettre les alliés hors de danger.",
	["GUIDE_TIP_128"] = "Glissement de terrain pour contrôler les foules.",
	["GUIDE_TIP_129"] = "Kill Command est votre attaque principale ; il envoie votre animal pour une grève.",
	["GUIDE_TIP_130"] = "Utilisez Barbed Shot pour raccourcir le temps de recharge de Bestial Wrath.",
	["GUIDE_TIP_131"] = "Bestial Wrath augmente vos dégâts et met votre animal en colère.",
	["GUIDE_TIP_132"] = "Kill Shot est votre finisseur pour les ennemis ayant moins de 20 % de santé.",
	["GUIDE_TIP_133"] = "Utilisez Multi-Shot pour activer Kill Cleave pour votre animal de compagnie.",
	["GUIDE_TIP_134"] = "L’exaltation vous guérit instantanément, vous et votre animal.",
	["GUIDE_TIP_135"] = "L'aspect de la tortue bloque tous les dégâts si vous avez des ennuis.",
	["GUIDE_TIP_136"] = "Counter Shot interrompt les sorts ennemis.",
	["GUIDE_TIP_137"] = "Une mauvaise direction sur votre animal de compagnie maintient une menace sur lui.",
	["GUIDE_TIP_138"] = "Mend Pet doit toujours être actif lorsque votre animal subit des dégâts.",
	["GUIDE_TIP_139"] = "Le tir visé fait le plus de dégâts ; ne gaspillez pas vos charges.",
	["GUIDE_TIP_140"] = "Rapid Fire génère de la Concentration et inflige de lourds dégâts.",
	["GUIDE_TIP_141"] = "Arcane Shot est votre principal moyen de dépenser votre Concentration.",
	["GUIDE_TIP_142"] = "Trueshot est votre gros temps de recharge pour les tirs ciblés rapides.",
	["GUIDE_TIP_143"] = "Multi-Shot active les Trick Shots pour les dégâts de zone.",
	["GUIDE_TIP_144"] = "L'aspect du guépard vous aide à vous déplacer rapidement.",
	["GUIDE_TIP_145"] = "Binding Shot maintient les groupes d’ennemis en place.",
	["GUIDE_TIP_146"] = "Freezing Trap assomme complètement un ennemi.",
	["GUIDE_TIP_147"] = "Utilisez Aspect de la tortue lors d'attaques dangereuses.",
	["GUIDE_TIP_148"] = "Feindre la mort permet aux monstres de vous ignorer lorsque les choses deviennent trop chaudes.",
