	["GUIDE_TIP_347"] = "Demonic Circle vous permet de vous téléporter instantanément dans un endroit sûr.",
	["GUIDE_TIP_348"] = "N'oubliez pas de fabriquer votre Healthstone ; c'est votre propre « potion » gratuite.",
	["GUIDE_TIP_349"] = "La Main de Gul'dan consomme vos éclats d'âme pour invoquer des diablotins sauvages.",
	["GUIDE_TIP_350"] = "Appeler Dreadstalkers doit être utilisé immédiatement dès que le temps de recharge est terminé.",
	["GUIDE_TIP_351"] = "Demonbolt génère 2 fragments d'âme ; utilisez-le lorsque « Demonic Core » s’allume.",
	["GUIDE_TIP_352"] = "Summon Demonic Tyrant augmente la durée de tous vos démons actifs et les rend plus forts.",
	["GUIDE_TIP_353"] = "L'implosion fait exploser tous vos diablotins, infligeant des dégâts massifs aux groupes d'ennemis.",
	["GUIDE_TIP_354"] = "Shadow Bolt est votre moyen de base de collecter des fragments d'âme.",
	["GUIDE_TIP_355"] = "La Force Démoniaque permet à votre Gangreguard d'effectuer un puissant décompte de tours.",
	["GUIDE_TIP_356"] = "Grimoire : Gangreguard invoque un deuxième garde pour des dégâts supplémentaires et un étourdissement.",
	["GUIDE_TIP_357"] = "Unending Resolve réduit les dégâts reçus et empêche vos sorts d’être interrompus.",
	["GUIDE_TIP_358"] = "Gardez votre Voidwalker actif pendant la mise à niveau afin qu'il encaisse tous les coups.",
	["GUIDE_TIP_359"] = "Chaos Bolt est votre attaque la plus puissante ; utilisez-le pour vider vos fragments d'âme.",
	["GUIDE_TIP_360"] = "Incinérer est votre remplissage pour construire des fragments d'éclat d'âme.",
	["GUIDE_TIP_361"] = "Conflagrate est instantané et vous donne un « Backdraft », rendant vos sorts suivants plus rapides.",
	["GUIDE_TIP_362"] = "Immolation devrait toujours brûler votre ennemi pour des dégâts constants et des fragments supplémentaires.",
	["GUIDE_TIP_363"] = "Invoquer Infernal est votre grand temps de recharge ; il pleut du feu et paralyse les ennemis à l'impact.",
	["GUIDE_TIP_364"] = "Rain of Fire est votre meilleure arme contre de grands groupes d'ennemis.",
	["GUIDE_TIP_365"] = "Shadowburn est parfait pour tuer rapidement des ennemis avec peu de vie.",
	["GUIDE_TIP_366"] = "Havoc permet également à vos sorts d'atteindre une deuxième cible ; essentiel pour les dommages « clivés ».",
	["GUIDE_TIP_367"] = "Command Demon vous permet d'utiliser la capacité spéciale de votre démon actif.",
	["GUIDE_TIP_368"] = "Utilisez Unending Resolve lorsque vous savez qu’un coup dur arrive.",
	["GUIDE_TIP_369"] = "Mortal Strike est votre coup le plus dur ; utilisez-le dès que possible pour dépenser de la rage.",
	["GUIDE_TIP_370"] = "La maîtrise ne peut pas être esquivée et amplifie votre prochaine frappe mortelle.",
	["GUIDE_TIP_371"] = "Colossus Smash brise l'armure de votre ennemi pour des phases de dégâts massifs.",
	["GUIDE_TIP_372"] = "Exécuter est votre finisseur mortel pour les ennemis ayant moins de 20 % de santé.",
	["GUIDE_TIP_373"] = "Bladestorm vous transforme en un tourbillon d'acier ; idéal pour les groupes d'ennemis.",
	["GUIDE_TIP_374"] = "Slam est votre attaque de remplissage si vous avez trop de rage et que d'autres attaques sont en temps de recharge.",
	["GUIDE_TIP_375"] = "Mourir par l'épée est votre meilleure défense ; il bloque presque toutes les attaques physiques.",
	["GUIDE_TIP_376"] = "Pummel interrompt les sorts ennemis ; ne laissez pas ces sorciers lancer !",
	["GUIDE_TIP_377"] = "Storm Bolt paralyse (étourdit) un ennemi à distance ; utile pour arrêter le danger.",
	["GUIDE_TIP_378"] = "La charge est le meilleur moyen d'ouvrir immédiatement le combat et de développer la Rage.",
	["GUIDE_TIP_379"] = "Rampage est votre attaque principale ; cela vous rend « enragé » pour plus de vitesse et de dégâts.",
	["GUIDE_TIP_380"] = "Bloodthirst vous guérit un peu et est votre principal générateur de Rage.",
	["GUIDE_TIP_381"] = "Raging Blow fait des dégâts importants et peut souvent être utilisé deux fois de suite.",
	["GUIDE_TIP_382"] = "Exécuter génère une tonne de rage et inflige de lourds dégâts aux ennemis faibles.",
	["GUIDE_TIP_383"] = "L'insouciance est votre grand temps de recharge ; vous obtenez 100 % de rage en plus et bien plus de critiques.",
	["GUIDE_TIP_384"] = "Whirlwind fait que vos 2 prochaines attaques touchent plusieurs ennemis ; essentiel pour AoE.",
	["GUIDE_TIP_385"] = "La régénération enragée vous soigne énormément tant que vous continuez à utiliser Bloodthirst.",
	["GUIDE_TIP_386"] = "Utilisez Pummel pour arrêter instantanément ces sorts ennemis ennuyeux.",
	["GUIDE_TIP_387"] = "Piercing Howl ralentit tous les ennemis autour de vous ; utile pour le contrôle.",
	["GUIDE_TIP_388"] = "Heroic Leap vous permet de parcourir de grandes distances ; parfait pour la mobilité.",
	["GUIDE_TIP_389"] = "Shield Slam est votre attaque de menace la plus puissante et génère beaucoup de rage.",
	["GUIDE_TIP_390"] = "Thunder Clap ralentit les ennemis et éloigne les groupes de monstres de vous.",
	["GUIDE_TIP_391"] = "La vengeance frappe fort après un blocage ou une esquive ; dégâts gratuits contre les groupes.",
	["GUIDE_TIP_392"] = "Le blocage de bouclier doit toujours être actif lorsque vous subissez des coups physiques de monstres.",
	["GUIDE_TIP_393"] = "Ignorer la douleur absorbe une grande partie des dégâts reçus ; utilisez votre Rage là-dessus.",
	["GUIDE_TIP_394"] = "Avatar vous transforme en géant ; vous faites plus de dégâts et vous évitez les retards.",
	["GUIDE_TIP_395"] = "Le Mur de Bouclier est votre défense la plus puissante ; utilisez-le si les choses menacent vraiment de mal tourner.",
	["GUIDE_TIP_396"] = "Last Stand augmente temporairement votre vie maximale; votre bouton d'urgence ultime.",
	["GUIDE_TIP_397"] = "Pummel est indispensable pour forcer les sorciers vers vous en arrêtant leurs lancers.",
	["GUIDE_TIP_398"] = "L'interception (ou la charge) vous aide à atteindre rapidement vos ennemis ou vos alliés.",
})

merge(ns._mhLocales and ns._mhLocales.esES, {
	["GUIDE_TIP_001"] = "Mantén siempre activos Moonfire y Sunfire en tu objetivo para causar daño en el tiempo.",
	["GUIDE_TIP_002"] = "Usa Wrath para activar Solar Eclipse y aumentar tu daño natural.",
	["GUIDE_TIP_003"] = "Usa Starfire durante el eclipse lunar para golpear a varios enemigos a la vez.",
	["GUIDE_TIP_004"] = "Starsurge es tu ataque más poderoso; Úsalo una vez que tengas suficiente poder astral.",
	["GUIDE_TIP_005"] = "Starfall es perfecto para grupos de monstruos; toca todo lo que está cerca.",
	["GUIDE_TIP_006"] = "No olvides a Barkskin cuando te ataquen; reduce el daño.",
	["GUIDE_TIP_007"] = "Typhoon es útil para volar a los enemigos si se acercan demasiado.",
	["GUIDE_TIP_008"] = "Calmar elimina la ira (Enfurecer) de los monstruos; muy útil en mazmorras.",
	["GUIDE_TIP_009"] = "Dash te ayuda a escapar rápidamente o correr hacia tu próximo objetivo más rápido.",
	["GUIDE_TIP_010"] = "Mantente siempre en forma Moonkin para obtener más daño y armadura adicional.",
	["GUIDE_TIP_011"] = "Comienza batallas con Rake from Prowl para obtener daño y sangrado adicionales.",
	["GUIDE_TIP_012"] = "Rip es tu principal rematador; Mantén siempre este sangrado activo en enemigos fuertes.",
	["GUIDE_TIP_013"] = "Usa Ferocious Bite como remate si tu enemigo está casi muerto o tu Rip ya está activo.",
	["GUIDE_TIP_014"] = "Triturar es tu ataque principal para acumular puntos de combo.",
	["GUIDE_TIP_015"] = "Tiger's Fury te da energía instantáneamente y aumenta tu daño; ¡Usa esto a menudo!",
	["GUIDE_TIP_016"] = "Thrash golpea a todos los enemigos a tu alrededor y los hace sangrar; Bueno para grupos.",
	["GUIDE_TIP_017"] = "Los instintos de supervivencia son tu defensa más fuerte; Úselo en caso de peligros importantes.",
	["GUIDE_TIP_018"] = "Skull Bash interrumpe los hechizos enemigos y te lleva directamente a tu objetivo.",
	["GUIDE_TIP_019"] = "Maim puede aturdir a un enemigo si quieres congelarlo por un momento.",
	["GUIDE_TIP_020"] = "Predatory Swiftness garantiza que a veces puedas utilizar Regrowth de forma inmediata y gratuita.",
	["GUIDE_TIP_021"] = "Usa Moonfire para tirar desde lejos, más seguro que saltar en la cara.",
	["GUIDE_TIP_022"] = "Bear Form es tu forma de tanque mientras subes de nivel; quédate en ella si recibes un golpe.",
	["GUIDE_TIP_023"] = "Ironfur mitiga los golpes físicos; recuérdalo contra élites y raros.",
	["GUIDE_TIP_024"] = "El gruñido ayuda si otro jugador se ve amenazado accidentalmente.",
	["GUIDE_TIP_025"] = "Golpea a múltiples enemigos; Mantenlo activo para amenazas AOE.",
	["GUIDE_TIP_026"] = "Mangle es un componente importante: úselo con frecuencia.",
	["GUIDE_TIP_027"] = "Barkskin es para momentos de \"ups\": no lo guardes por mucho tiempo hasta que estés casi muerto.",
	["GUIDE_TIP_028"] = "Regeneración frenética: cura a tiempo, no en el último minuto.",
	["GUIDE_TIP_029"] = "Mantenga activa Mark of the Wild; Esta mejora gratuita proporciona estadísticas adicionales y hace que cada extracción sea un poco más segura.",
	["GUIDE_TIP_030"] = "Skull Bash interrumpe los lanzamientos enemigos: aprende a tenerlo listo en las mazmorras.",
	["GUIDE_TIP_031"] = "Mantenga siempre activo el Rejuvenecimiento en el tanque para una curación constante.",
	["GUIDE_TIP_032"] = "Lifebloom siempre debe estar en el tanque; da una gran curación cuando expira.",
	["GUIDE_TIP_033"] = "Utilice Crecimiento salvaje si todo el grupo sufre daño.",
	["GUIDE_TIP_034"] = "El recrecimiento es su cura rápida para emergencias.",
	["GUIDE_TIP_035"] = "Swiftmend brinda una gran curación inmediata, pero primero debes tener Rejuvenecimiento en el objetivo.",
	["GUIDE_TIP_036"] = "Coloque Eflorescencia (el círculo) donde esté parada la mayoría de la gente.",
	["GUIDE_TIP_037"] = "Usa Moonfire y Sunfire para ayudar con el daño si nadie muere.",
	["GUIDE_TIP_038"] = "Ironbark reduce el daño que recibe el tanque; Úsalo para grandes éxitos.",
	["GUIDE_TIP_039"] = "Usa Innervate en ti mismo si tienes poco maná y necesitas curarte mucho.",
	["GUIDE_TIP_040"] = "La Rapidez de la Naturaleza hace que tu próximo Recrecimiento sea gratuito e instantáneo.",
	["GUIDE_TIP_041"] = "Death Strike es tu botón más importante; te cura y te da un escudo después del daño.",
	["GUIDE_TIP_042"] = "Marrowrend construye Bone Shield. Mantén siempre esto por encima de 5 acumulaciones para obtener armadura adicional.",
	["GUIDE_TIP_043"] = "Heart Strike es tu ataque de relleno para generar poder rúnico, especialmente en Death and Decay.",
	["GUIDE_TIP_044"] = "Entrega muerte y decadencia a grupos de enemigos para que tu Heart Strike alcance múltiples objetivos.",
	["GUIDE_TIP_045"] = "Blood Boil propaga tus enfermedades y ayuda a mantener la atención de todos los monstruos.",
	["GUIDE_TIP_046"] = "Dancing Rune Weapon es una defensa fuerte que te ayuda a detener ataques.",
	["GUIDE_TIP_047"] = "La sangre vampírica te da temporalmente mucha más vida; Úselo si está en peligro.",
	["GUIDE_TIP_048"] = "Anti-Magic Shell bloquea el daño mágico y evita que sufras efectos adversos.",
	["GUIDE_TIP_049"] = "Asfixiar paraliza a un enemigo durante unos segundos; Útil para detener hechizos peligrosos.",
	["GUIDE_TIP_050"] = "Death Grip atrae instantáneamente a un enemigo hacia ti. Perfecto para recuperar a los fugitivos.",
