	["GUIDE_TIP_052"] = "Howling Blast aplica Frost Fever. Úselo siempre cuando el proceso Rime se ilumine.",
	["GUIDE_TIP_053"] = "Destruir es tu principal ataque. Úsalo cuando tengas procs de Killing Machine para daño crítico.",
