	["GUIDE_TIP_150"] = "Wildfire Bomb es tu principal fuente de daño a lo largo del tiempo.",
	["GUIDE_TIP_151"] = "Mongoose Bite es tu ataque más fuerte; intenta construir pilas.",
	["GUIDE_TIP_152"] = "Mantén siempre activo Serpent Sting en enemigos fuertes.",
	["GUIDE_TIP_153"] = "Asalto Coordinado fortalece la colaboración con tu mascota.",
	["GUIDE_TIP_154"] = "Harpoon te lleva directamente hacia tu enemigo.",
	["GUIDE_TIP_155"] = "Fury of the Eagle es un poderoso ataque para grupos de monstruos.",
	["GUIDE_TIP_156"] = "Aspecto de la Tortuga para máxima defensa.",
	["GUIDE_TIP_157"] = "La intimidación permite que tu mascota aturda al objetivo.",
	["GUIDE_TIP_158"] = "Desenganchate para saltar rápidamente hacia atrás y distanciarte.",
	["GUIDE_TIP_159"] = "Arcane Blast es tu base; cuantas más acumulaciones, más fuerte será el golpe (y más maná).",
	["GUIDE_TIP_160"] = "Solo usa Misiles Arcanos cuando Clearcasting esté activo para un ataque gratuito.",
