	["GUIDE_TIP_164"] = "Arcane Surge es tu ataque más poderoso; Consume todo tu maná para causar un daño masivo y luego lo regenera rápidamente.",
	["GUIDE_TIP_165"] = "Mirror Image invoca tres copias de ti mismo para distraer a los enemigos y reducir el daño.",
