	["GUIDE_TIP_167"] = "El contrahechizo detiene los hechizos enemigos; esencial en mazmorras y contra monstruos de élite.",
	["GUIDE_TIP_168"] = "No olvides el Intelecto Arcano; Este beneficio siempre debe estar activo para aumentar el daño y el maná.",
