	["GUIDE_TIP_395"] = "Shield Wall es tu defensa más fuerte; Úselo si las cosas realmente amenazan con salir mal.",
	["GUIDE_TIP_396"] = "Last Stand aumenta temporalmente tu vida máxima; Tu botón de emergencia definitivo.",
