merge(ns._mhLocales and ns._mhLocales.ruRU, {
	["GUIDE_TIP_001"] = "Всегда держите Лунный огонь и Солнечный огонь активными на своей цели, чтобы наносить постепенный урон.",
	["GUIDE_TIP_002"] = "Используйте «Гнев», чтобы активировать «Солнечное затмение» и увеличить урон от сил природы.",
	["GUIDE_TIP_003"] = "Используйте «Звездный огонь» во время лунного затмения, чтобы поразить нескольких врагов одновременно.",
	["GUIDE_TIP_004"] = "Звездный поток — ваша самая мощная атака; используйте это, как только у вас будет достаточно астральной силы.",
	["GUIDE_TIP_005"] = "Звездопад идеально подходит для групп монстров; оно касается всего, что находится рядом.",
	["GUIDE_TIP_006"] = "Не забудьте Barkskin, когда на вас нападут; это уменьшает урон.",
	["GUIDE_TIP_007"] = "Тайфун полезен для того, чтобы сдуть врагов, если они подошли слишком близко.",
	["GUIDE_TIP_008"] = "Успокоение снимает гнев (исступление) с монстров; очень полезен в подземельях.",
	["GUIDE_TIP_009"] = "Dash поможет вам быстро сбежать или быстрее добежать до следующей цели.",
	["GUIDE_TIP_010"] = "Всегда оставайтесь в форме лунного совуха, чтобы получить больше урона и дополнительную броню.",
	["GUIDE_TIP_011"] = "Начинайте сражения с Рейком из Проула, чтобы получить дополнительный урон и кровотечение.",
	["GUIDE_TIP_012"] = "Рип — ваш главный финишер; всегда оставляйте это кровотечение активным на сильных врагах.",
	["GUIDE_TIP_013"] = "Используйте «Свирепый укус» в качестве финишера, если ваш враг почти мертв или ваш «Разорвать» уже активен.",
	["GUIDE_TIP_014"] = "Shred — ваша основная атака для накопления комбо-очков.",
	["GUIDE_TIP_015"] = "«Ярость тигра» мгновенно дает вам энергию и увеличивает ваш урон; используйте это часто!",
	["GUIDE_TIP_016"] = "Трэш поражает всех врагов вокруг вас и вызывает у них кровотечение; хорошо для групп.",
	["GUIDE_TIP_017"] = "Инстинкты выживания — ваша самая сильная защита; используйте это в случае серьезной опасности.",
	["GUIDE_TIP_018"] = "Skull Bash прерывает заклинания противника и переносит вас прямо к цели.",
	["GUIDE_TIP_019"] = "Maim может оглушить врага, если вы хотите заморозить его на мгновение.",
	["GUIDE_TIP_020"] = "Хищная стремительность гарантирует, что иногда вы можете использовать «Восстановление» немедленно и бесплатно.",
	["GUIDE_TIP_021"] = "Используйте Лунный огонь, чтобы тянуть издалека — безопаснее, чем прыгать в лицо.",
	["GUIDE_TIP_022"] = "Форма медведя — это ваша форма танка во время прокачки уровня — оставайтесь в ней, если получите удар.",
	["GUIDE_TIP_023"] = "Железный мех смягчает физические удары — помните об этом против элитных и редких существ.",
	["GUIDE_TIP_024"] = "Рычание помогает, если другой игрок случайно принимает на себя угрозу.",
	["GUIDE_TIP_025"] = "Избить нескольких врагов; держите его активным для угрозы AOE.",
	["GUIDE_TIP_026"] = "Mangle — важный строительный блок — используйте его часто.",
	["GUIDE_TIP_027"] = "Дубовая кожа предназначена для моментов «упс» — не держите ее слишком долго, пока вы почти не умрете.",
	["GUIDE_TIP_028"] = "Бешеная регенерация: исцеляйтесь вовремя, а не в последнюю минуту.",
	["GUIDE_TIP_029"] = "Держите Знак дикой природы активным; этот бесплатный бафф дает дополнительные характеристики и делает каждое нажатие немного безопаснее.",
	["GUIDE_TIP_030"] = "Skull Bash прерывает заклинания противника — научитесь готовить его в подземельях.",
	["GUIDE_TIP_031"] = "Всегда держите «Омоложение» активным на танке для постоянного лечения.",
	["GUIDE_TIP_032"] = "Lifebloom всегда должен быть на танке; он дает большое исцеление, когда срок его действия истекает.",
	["GUIDE_TIP_033"] = "Используйте «Буйный рост», если вся группа получила урон.",
	["GUIDE_TIP_034"] = "Восстановление роста — это ваше быстрое исцеление в чрезвычайных ситуациях.",
	["GUIDE_TIP_035"] = "«Быстрое восстановление» дает немедленное мощное исцеление, но сначала вы должны использовать «Омоложение» на цели.",
	["GUIDE_TIP_036"] = "Поместите Цветение (круг) там, где стоит большинство людей.",
	["GUIDE_TIP_037"] = "Используйте Лунный огонь и Солнечный огонь, чтобы помочь с уроном, если никто не погибнет.",
	["GUIDE_TIP_038"] = "Ironbark уменьшает получаемый танком урон; используйте это для больших хитов.",
	["GUIDE_TIP_039"] = "Используйте Innervate на себя, если у вас мало маны и вам нужно много лечить.",
	["GUIDE_TIP_040"] = "Природная стремительность делает ваше следующее восстановление бесплатным и мгновенным.",
	["GUIDE_TIP_041"] = "«Удар смерти» — ваша самая важная кнопка; он исцеляет вас и дает щит после урона.",
	["GUIDE_TIP_042"] = "Марроуренд создает костяной щит. Всегда держите это количество выше 5, чтобы получить дополнительную броню.",
	["GUIDE_TIP_043"] = "Удар сердца — ваша дополнительная атака для увеличения рунической силы, особенно в «Смерти и разложении».",
	["GUIDE_TIP_044"] = "Несите смерть и разложение группам врагов, чтобы ваш «Удар сердца» поразил несколько целей.",
	["GUIDE_TIP_045"] = "Кипение крови распространяет ваши болезни и помогает удерживать внимание всех монстров.",
	["GUIDE_TIP_046"] = "Танцующее руническое оружие — мощная защита, помогающая парировать атаки.",
	["GUIDE_TIP_047"] = "Вампирская кровь временно дает вам гораздо больше жизни; используйте это, если вы в опасности.",
	["GUIDE_TIP_048"] = "Антимагический панцирь блокирует магический урон и защищает вас от побочных эффектов.",
	["GUIDE_TIP_049"] = "Удушье парализует врага на несколько секунд; полезен для остановки опасных заклинаний.",
	["GUIDE_TIP_050"] = "«Хватка смерти» мгновенно притягивает к вам врага. Идеально подходит для поиска беглецов.",
	["GUIDE_TIP_051"] = "«Ледяной удар» — ваш основной способ потратить силу рун.",
	["GUIDE_TIP_052"] = "«Воющий ветер» применяет «Ледяную лихорадку». Всегда используйте его, когда загорается прок Rime.",
	["GUIDE_TIP_053"] = "Уничтожение — ваша основная атака. Используйте это, когда у вас есть проки «Машины для убийств» для нанесения критического урона.",
	["GUIDE_TIP_054"] = "Remorseless Winter наносит постоянный урон вокруг вас; идеально подходит для групп монстров.",
	["GUIDE_TIP_055"] = "«Ледяной столп» значительно увеличивает вашу силу; используйте это в каждом крупном сражении.",
	["GUIDE_TIP_056"] = "Усиление рунического оружия мгновенно возвращает вам руны и руническую силу для дополнительного взрыва.",
	["GUIDE_TIP_057"] = "Ледяные цепи чрезвычайно замедляют врагов; полезно для поддержания дистанции или остановки кого-либо.",
	["GUIDE_TIP_058"] = "Mind Freeze — ваш «удар», позволяющий прерывать вражеские заклинания.",
	["GUIDE_TIP_059"] = "Не забудьте «Удар смерти», если у вас мало жизни; это стоит рунической силы, но спасает вашу жизнь.",
	["GUIDE_TIP_060"] = "Вспышка мгновенно заражает всех врагов опасной чумой. Начинайте каждую битву с этого.",
	["GUIDE_TIP_061"] = "«Гнойный удар» накладывает на вашу цель «Гнойные раны».",
	["GUIDE_TIP_062"] = "Удар Плети взрывает Гнойные раны, нанося большой урон.",
	["GUIDE_TIP_063"] = "Death Coil — ваш источник рунической силы; это усиливает вашего Гуля.",
	["GUIDE_TIP_064"] = "Апокалипсис призывает армии нежити, взрывая «Гнойные раны». Используйте это для взрыва.",
	["GUIDE_TIP_065"] = "Темная трансформация превращает вашего гуля в чудовищного зверя с новыми способностями.",
	["GUIDE_TIP_066"] = "Армия Мертвых призывает огромную армию; оставьте это для самых сложных боссов.",
	["GUIDE_TIP_067"] = "Сражайтесь в режиме «Смерть и разложение», чтобы «Удар Плети» поразил сразу несколько врагов.",
	["GUIDE_TIP_068"] = "Антимагический панцирь необходим для отмены магических заклинаний во время боя.",
	["GUIDE_TIP_069"] = "Chaos Strike — ваш главный тратитель.",
	["GUIDE_TIP_070"] = "Используйте «Танец клинков» во время восстановления для AoE.",
	["GUIDE_TIP_071"] = "Eye Beam дает вам Metamorphosis; используйте его часто.",
	["GUIDE_TIP_072"] = "Fel Rush для передвижения и урона.",
	["GUIDE_TIP_073"] = "Размытие — ваша лучшая защита.",
	["GUIDE_TIP_074"] = "Мстительное отступление, чтобы получить Ярость.",
	["GUIDE_TIP_075"] = "Метаморфоза для большого взрыва.",
	["GUIDE_TIP_076"] = "Immolation Aura для пассивного AoE.",
	["GUIDE_TIP_077"] = "Disrupt, чтобы прервать заклинания.",
	["GUIDE_TIP_078"] = "Используйте магию, чтобы рассеять врагов.",
	["GUIDE_TIP_079"] = "Soul Carver для большого урона/исцеления.",
	["GUIDE_TIP_080"] = "Демонические шипы должны быть активны при получении физических ударов.",
	["GUIDE_TIP_081"] = "Immolation Aura генерирует ярость.",
	["GUIDE_TIP_082"] = "«Опустошение Скверны» — это ваше дерьмовое исцеление.",
	["GUIDE_TIP_083"] = "Сигил Пламени для притягивания/AoE.",
	["GUIDE_TIP_084"] = "Адский удар для мобильности.",
	["GUIDE_TIP_085"] = "Стеки хрупкости помогут вам выжить.",
	["GUIDE_TIP_086"] = "Символ молчания для заклинателей.",
	["GUIDE_TIP_087"] = "Метаморфоза для максимального HP.",
	["GUIDE_TIP_088"] = "Бросьте Глефу, чтобы подобрать аддов.",
	["GUIDE_TIP_089"] = "Стрела Бездны — ваше основное заклинание, наносящее урон.",
	["GUIDE_TIP_090"] = "Используйте Потребитель душ для лечения.",
	["GUIDE_TIP_091"] = "Essence Tear для нанесения AoE-урона.",
	["GUIDE_TIP_092"] = "Метаморфоза Бездны — ваш большой взрыв.",
	["GUIDE_TIP_093"] = "Кольцо Хаоса для оглушения.",
	["GUIDE_TIP_094"] = "Спектральное зрение для поиска скрытых врагов.",
	["GUIDE_TIP_095"] = "Тюрьма за CC.",
	["GUIDE_TIP_096"] = "Путь по Пустоте, чтобы избежать повреждений.",
	["GUIDE_TIP_097"] = "Символ молчания, останавливающий заклинателей.",
	["GUIDE_TIP_098"] = "Glaive Toss для вытягивания.",
	["GUIDE_TIP_099"] = "Дезинтеграция — ваш основной источник затрат на одиночные цели.",
	["GUIDE_TIP_100"] = "Костер для AoE-групп.",
	["GUIDE_TIP_101"] = "Всегда держите «Огненное дыхание» на перезарядке (обычно достаточно уровня 1 Empower).",
	["GUIDE_TIP_102"] = "Eternity Surge отлично подходит для нескольких целей.",
	["GUIDE_TIP_103"] = "Используйте Живое Пламя в качестве наполнителя.",
	["GUIDE_TIP_104"] = "Hover позволяет вам кастовать во время движения; пользуйтесь им часто!",
	["GUIDE_TIP_105"] = "Драконья ярость — это ваше большое время восстановления.",
	["GUIDE_TIP_106"] = "Обсидиановые чешуйки для защиты.",
	["GUIDE_TIP_107"] = "Quell, чтобы прервать врагов.",
	["GUIDE_TIP_108"] = "Оползень, чтобы обездвижить врагов на месте.",
	["GUIDE_TIP_109"] = "Эхо — ваш самый важный комбинированный инструмент.",
	["GUIDE_TIP_110"] = "«Дыхание мечты» — это массовое групповое исцеление (при необходимости усиливаете).",
	["GUIDE_TIP_111"] = "Spiritbloom для быстрого исцеления нескольких целей.",
	["GUIDE_TIP_112"] = "Используйте Reversion, чтобы держать людей в курсе событий.",
	["GUIDE_TIP_113"] = "Verdant Embrace — мощное целенаправленное лечение.",
	["GUIDE_TIP_114"] = "Перемотка может спасти группу после резкого всплеска урона.",
	["GUIDE_TIP_115"] = "Временная аномалия обеспечивает щитами всех, кого касается.",
	["GUIDE_TIP_116"] = "Dream Flight для высокомобильного лечения.",
	["GUIDE_TIP_117"] = "Изумрудный цвет для дешевого лечения по площади.",
	["GUIDE_TIP_118"] = "Стазис для хранения и повторения ваших лучших исцелений.",
	["GUIDE_TIP_119"] = "«Эбеновая мощь» должна иметь 100% работоспособность, чтобы усилить ваших союзников.",
	["GUIDE_TIP_120"] = "Переворот продлевает ваши положительные эффекты.",
	["GUIDE_TIP_121"] = "«Дыхание вечности» — ваше большое время восстановления; приурочите это к взрыву вашей группы.",
	["GUIDE_TIP_122"] = "Вздутие чешуи на баке.",
	["GUIDE_TIP_123"] = "Предвидение ваших лучших игроков DPS.",
	["GUIDE_TIP_124"] = "Извержение — ваш основной ресурс для продления «Эбеновой мощи».",
	["GUIDE_TIP_125"] = "Источник магии для маны ваших целителей.",
	["GUIDE_TIP_126"] = "Пространственный парадокс помогает целителям применять заклинания во время движения.",
	["GUIDE_TIP_127"] = "Спасение, чтобы вывести союзников из опасности.",
	["GUIDE_TIP_128"] = "Оползень для сдерживания толпы.",
	["GUIDE_TIP_129"] = "Команда «Kill Command» — ваша основная атака; он отправляет вашего питомца на забастовку.",
	["GUIDE_TIP_130"] = "Используйте «Колючий выстрел», чтобы сократить время восстановления «Звериного гнева».",
	["GUIDE_TIP_131"] = "Звериный гнев увеличивает ваш урон и приводит в ярость вашего питомца.",
	["GUIDE_TIP_132"] = "Kill Shot — ваш финишер для врагов, у которых осталось менее 20% здоровья.",
	["GUIDE_TIP_133"] = "Используйте Multi-Shot, чтобы активировать Kill Cleave для вашего питомца.",
	["GUIDE_TIP_134"] = "Возбуждение мгновенно исцеляет вас и вашего питомца.",
	["GUIDE_TIP_135"] = "Аспект Черепахи блокирует весь урон, если вы попали в беду.",
	["GUIDE_TIP_136"] = "Counter Shot прерывает заклинания противника.",
	["GUIDE_TIP_137"] = "Неправильное направление вашего питомца сохраняет для него угрозу.",
	["GUIDE_TIP_138"] = "«Mend Pet» всегда должен быть активен, когда ваш питомец получает урон.",
	["GUIDE_TIP_139"] = "Прицельный выстрел наносит наибольший урон; не тратьте свои расходы.",
	["GUIDE_TIP_140"] = "Rapid Fire генерирует концентрацию и наносит тяжелый урон.",
	["GUIDE_TIP_141"] = "Чародейский выстрел — ваш основной способ потратить Фокус.",
	["GUIDE_TIP_142"] = "Trueshot — ваше большое время восстановления для быстрых прицельных выстрелов.",
	["GUIDE_TIP_143"] = "Multi-Shot активирует Trick Shots для нанесения AoE-урона.",
	["GUIDE_TIP_144"] = "Аспект гепарда помогает вам двигаться быстро.",
	["GUIDE_TIP_145"] = "Binding Shot удерживает группы врагов на месте.",
	["GUIDE_TIP_146"] = "Freezing Trap полностью вырубает одного врага.",
	["GUIDE_TIP_147"] = "Используйте аспект черепахи при опасных атаках.",
	["GUIDE_TIP_148"] = "Притвориться смертью позволяет монстрам игнорировать вас, когда ситуация становится слишком жаркой.",
	["GUIDE_TIP_149"] = "Команда «Kill Command» генерирует концентрацию для ваших атак.",
	["GUIDE_TIP_150"] = "Wildfire Bomb — ваш основной источник постепенного урона.",
	["GUIDE_TIP_151"] = "Укус мангуста — ваша самая сильная атака; попробуйте построить стеки.",
	["GUIDE_TIP_152"] = "Всегда держите Змеиное жало активным против сильных врагов.",
	["GUIDE_TIP_153"] = "Скоординированное нападение укрепляет сотрудничество с вашим питомцем.",
	["GUIDE_TIP_154"] = "Гарпун притягивает вас прямо к врагу.",
	["GUIDE_TIP_155"] = "Ярость орла — мощная атака для групп монстров.",
	["GUIDE_TIP_156"] = "Аспект Черепахи для максимальной защиты.",
	["GUIDE_TIP_157"] = "Устрашение позволяет вашему питомцу оглушить цель.",
	["GUIDE_TIP_158"] = "Выйдите из боя, чтобы быстро отпрыгнуть назад и дистанцироваться.",
	["GUIDE_TIP_159"] = "Чародейская вспышка — ваша база; чем больше стаков, тем сильнее удар (и тем больше маны).",
	["GUIDE_TIP_160"] = "Используйте Чародейские стрелы только при активном «Ясном мышлении» для свободной атаки.",
	["GUIDE_TIP_161"] = "Чародейский обстрел истощает ваши заряды и дает немного отдохнуть мане.",
	["GUIDE_TIP_162"] = "Вызывание — ваш спасательный круг; используйте его, чтобы очень быстро пополнить свою ману.",
	["GUIDE_TIP_163"] = "Alter Time — ваш лучший друг: он возвращает вашу жизнь и место на 10 секунд назад.",
	["GUIDE_TIP_164"] = "Чародейская волна — ваша самая мощная атака; он потребляет всю вашу ману для нанесения огромного урона, а затем быстро восстанавливает ее.",
	["GUIDE_TIP_165"] = "Зеркальное изображение вызывает три ваши копии, чтобы отвлечь врагов и уменьшить урон.",
	["GUIDE_TIP_166"] = "Замедление идеально подходит для того, чтобы держать на расстоянии одного сильного врага, пока вы заряжаете свои заклинания.",
	["GUIDE_TIP_167"] = "Контрзаклинание останавливает вражеские заклинания; необходим в подземельях и против элитных монстров.",
	["GUIDE_TIP_168"] = "Не забывайте Тайный интеллект; этот бафф всегда должен быть активен для увеличения урона и маны.",
	["GUIDE_TIP_169"] = "Удерживайте Огненный шар, пока не получите критический удар (Нагрев).",
	["GUIDE_TIP_170"] = "Fire Blast гарантирует крит; используйте это, чтобы мгновенно активировать свою полосу удачи.",
	["GUIDE_TIP_171"] = "Используйте Огненную глыбу только мгновенно (Hot Streak) для максимального хаоса.",
	["GUIDE_TIP_172"] = "Горение — это ваше окно взрыва; тогда все, что вас касается, имеет решающее значение.",
	["GUIDE_TIP_173"] = "Flamestrike — король AoE; идеально подходит для больших групп.",
	["GUIDE_TIP_174"] = "Дыхание Дракона дезориентирует всех врагов перед вами; идеально, если они подойдут слишком близко.",
	["GUIDE_TIP_175"] = "Phoenix Flames дает вам гарантированный критический удар и помогает создать Hot Streak.",
	["GUIDE_TIP_176"] = "Вы можете использовать Scorch во время бега; идеально подходит для случаев, когда вам нужно увернуться, но вы все равно хотите атаковать.",
	["GUIDE_TIP_177"] = "Используйте Counterspell, чтобы мгновенно прерывать опасные заклинания противника.",
	["GUIDE_TIP_178"] = "Пылающий барьер поглощает урон и наносит часть урона от огня атакующим.",
	["GUIDE_TIP_179"] = "Ледяная стрела замедляет врагов, чтобы они никогда не могли вас коснуться.",
	["GUIDE_TIP_180"] = "Вам следует использовать Flurry сразу же, как только загорится Brain Freeze для комбо.",
	["GUIDE_TIP_181"] = "Ледяное копье наносит тройной урон замороженным врагам.",
	["GUIDE_TIP_182"] = "Frozen Orb постоянно генерирует ледяные пальцы; идеально подходит для групп.",
	["GUIDE_TIP_183"] = "Ледяная глыба — ваша кнопка экстренной помощи; делает вас неуязвимым на 10 секунд.",
	["GUIDE_TIP_184"] = "Ваш элементаль воды может замораживать врагов, что мгновенно дает вам срабатывание Ледяных пальцев.",
	["GUIDE_TIP_185"] = "Icy Veins позволяет вам кастовать намного быстрее; используйте это с большими группами или боссами.",
	["GUIDE_TIP_186"] = "Конус холода замедляет всех врагов в конусе перед вами; полезно для побега.",
	["GUIDE_TIP_187"] = "Прерывайте врагов с помощью Counterspell, чтобы они не нанесли вам урон.",
	["GUIDE_TIP_188"] = "Ледяной барьер — ваш главный щит; старайтесь всегда активировать это во время сражений.",
	["GUIDE_TIP_189"] = "Keg Smash — ваша основная угроза, замедляющая врагов.",
	["GUIDE_TIP_190"] = "Blackout Kick сокращает время восстановления вашего напитка; используйте его часто.",
	["GUIDE_TIP_191"] = "Дыхание Огня сжигает врагов; они наносят меньше урона при ударе бочонком.",
	["GUIDE_TIP_192"] = "Очищающий отвар необходим для уменьшения вдвое вашего шатания (сохраняется урон).",
	["GUIDE_TIP_193"] = "Небесное отвар дает вам огромный щит, зависящий от количества нанесенного вами урона.",
	["GUIDE_TIP_194"] = "Стремительный нефритовый ветер наносит постоянный урон вокруг вас; хорошо подходит для проведения групп.",
	["GUIDE_TIP_195"] = "Укрепляющий отвар — это ваша аварийная кнопка для увеличения жизни и уменьшения входящего урона.",
	["GUIDE_TIP_196"] = "Expel Harm мгновенно исцеляет вас и притягивает к вам все сферы исцеления.",
	["GUIDE_TIP_197"] = "Удар копья прерывает вражеские заклинания.",
	["GUIDE_TIP_198"] = "Leg Sweep оглушает всех врагов вокруг вас на несколько секунд.",
	["GUIDE_TIP_199"] = "Успокаивающий туман — основа вашего исцеления; вы можете использовать другие заклинания непосредственно во время произнесения этого заклинания.",
	["GUIDE_TIP_200"] = "Обновляющийся туман распространяется на раненых союзников; распространите это как можно большему количеству людей.",
	["GUIDE_TIP_201"] = "«Окутывающий туман» обеспечивает мощное исцеление с течением времени и усиливает другие исцеления этой цели.",
	["GUIDE_TIP_202"] = "Оживление исцеляет вашу основную цель и всех, у кого есть Обновляющий туман.",
	["GUIDE_TIP_203"] = "Essence Font — ваш лучший вариант для одновременного исцеления всей группы.",
	["GUIDE_TIP_204"] = "Возрождение — это огромное мгновенное лечение для всего рейда и снятие всех негативных эффектов.",
	["GUIDE_TIP_205"] = "Life Cocoon дает союзнику большой щит и увеличивает получаемое им исцеление.",
	["GUIDE_TIP_206"] = "Чай Thunder Focus усиливает ваше следующее заклинание; используйте его с умом.",
	["GUIDE_TIP_207"] = "Используйте «Размах ног», чтобы оглушить врагов и уменьшить урон, наносимый танку.",
	["GUIDE_TIP_208"] = "Паралич полностью заставляет врага замолчать; полезно, чтобы облегчить бой.",
	["GUIDE_TIP_209"] = "Тигровая ладонь развивает Ци; никогда не используйте его дважды подряд (Мастерство!).",
	["GUIDE_TIP_210"] = "Blackout Kick — дешевый способ продолжить серию комбо.",
	["GUIDE_TIP_211"] = "«Удар восходящего солнца» — ваша самая сильная атака против одной цели.",
	["GUIDE_TIP_212"] = "Fists of Fury наносит огромный урон всем врагам перед вами; оставаться неподвижным во время использования.",
	["GUIDE_TIP_213"] = "Удар вращающегося журавля — ваша лучшая атака против больших групп монстров.",
	["GUIDE_TIP_214"] = "Прикосновение смерти мгновенно убивает врагов, у которых меньше здоровья, чем у вас; используйте его при каждом удобном случае.",
	["GUIDE_TIP_215"] = "Touch of Karma отправляет входящий урон обратно вашему врагу; твоя лучшая защита.",
	["GUIDE_TIP_216"] = "Волна Ци перемещается между союзниками и врагами, нанося как урон, так и исцеление.",
	["GUIDE_TIP_217"] = "Используйте «Удар копья», чтобы остановить опасные заклинания врагов.",
	["GUIDE_TIP_218"] = "Flying Serpent Kick поможет вам перемещаться по миру или сражаться с молниеносной скоростью.",
	["GUIDE_TIP_219"] = "Святой шок — ваше основное заклинание; используйте его как для быстрого исцеления, так и для нанесения урона.",
	["GUIDE_TIP_220"] = "«Слово Славы» — лучший способ потратить Святую Силу на мгновенное исцеление.",
	["GUIDE_TIP_221"] = "Вспышка света быстрая, но дорогая; используйте его только в экстренных ситуациях.",
	["GUIDE_TIP_222"] = "Всегда держите «Маяк света» на танке, чтобы он получал исцеление, пока вы помогаете другим.",
	["GUIDE_TIP_223"] = "Avenging Wrath (Wings) значительно увеличивает исцеление и урон; приберегите это для трудных моментов.",
	["GUIDE_TIP_224"] = "Молот Света отлично подходит для исцеления группы, находящейся близко друг к другу.",
	["GUIDE_TIP_225"] = "Божественная защита уменьшает получаемый вами урон; не забывайте защищать себя!",
	["GUIDE_TIP_226"] = "«Молот правосудия» оглушает врага на 6 секунд; идеально подходит для остановки опасных заклинаний.",
	["GUIDE_TIP_227"] = "Благословение свободы снимает с вас или союзника эффекты, ограничивающие передвижение.",
	["GUIDE_TIP_228"] = "«Возложение рук» мгновенно исцеляет цель на 100% от вашего максимального запаса здоровья; ваша лучшая кнопка экстренной помощи.",
	["GUIDE_TIP_229"] = "Щит праведника — ваша главная защита; это значительно увеличивает вашу броню.",
	["GUIDE_TIP_230"] = "Щит Мстителя прерывает врагов и дает вам щит; используйте его, как только сможете.",
	["GUIDE_TIP_231"] = "Освящение всегда должно быть под ногами для дополнительного снижения урона.",
	["GUIDE_TIP_232"] = "Crusader Strike накапливает Святую Силу, необходимую вам для защиты или исцеления.",
	["GUIDE_TIP_233"] = "Правосудие генерирует Святую Силу и заставляет ваших врагов наносить более сильные удары.",
	["GUIDE_TIP_234"] = "Серафим на короткое время увеличивает все ваши второстепенные характеристики; используйте его для дополнительной силы.",
	["GUIDE_TIP_235"] = "Guardian of Ancient Kings — ваша сильнейшая защита от массированных ударов.",
	["GUIDE_TIP_236"] = "Ardent Defender не дает вам умереть от смертельного удара; незаменимое спасение.",
	["GUIDE_TIP_237"] = "Рука Возмездия привлекает к вам внимание монстра (Провокация).",
	["GUIDE_TIP_238"] = "«Молот праведника» — ваша основная атака против групп врагов.",
	["GUIDE_TIP_239"] = "Вердикт тамплиера — ваша самая мощная атака; используйте его, как только у вас будет 3 или более Святой Силы.",
	["GUIDE_TIP_240"] = "Клинок Справедливости быстро накапливает Святую Силу; используйте его во время восстановления.",
	["GUIDE_TIP_241"] = "Правосудие гарантирует, что ваша следующая атака Силы Света получит больше урона.",
	["GUIDE_TIP_242"] = "Crusader Strike — ваша базовая атака, позволяющая заполнить пробелы в вашей ротации.",
	["GUIDE_TIP_243"] = "Divine Storm — ваше лучшее оружие против групп врагов; это влияет на всех вокруг вас.",
	["GUIDE_TIP_244"] = "«Молот гнева» можно использовать только против врагов с низким уровнем жизни или во время действия «Крылья».",
	["GUIDE_TIP_245"] = "Avenging Wrath (Wings) делает все ваши атаки намного сильнее; используйте это для максимального взрыва.",
	["GUIDE_TIP_246"] = "Щит возмездия поглощает урон, а затем взрывается, нанося дополнительный урон врагам.",
	["GUIDE_TIP_247"] = "Divine Shield (Bubble) делает вас полностью неуязвимым; идеально подходит для выживания в опасных ситуациях.",
	["GUIDE_TIP_248"] = "Божественный скакун поможет вам быстро передвигаться в пылу битвы.",
	["GUIDE_TIP_249"] = "Искупление — ваш самый важный механизм; исцеляйте союзников, нанося урон врагам.",
	["GUIDE_TIP_250"] = "Слово силы: Щит мгновенно усиливает эффект и применяет к цели «Искупление вины».",
	["GUIDE_TIP_251"] = "Покаяние — ваше самое универсальное заклинание; используйте его для взрывного урона или мгновенного исцеления.",
	["GUIDE_TIP_252"] = "Smite — ваша базовая атака, позволяющая поддерживать активное исцеление «Искупления вины», не потребляя много маны.",
	["GUIDE_TIP_253"] = "Mind Blast наносит значительный урон и предотвращает часть последующего урона противника.",
	["GUIDE_TIP_254"] = "Подавление боли значительно снижает входящий урон; используйте это на танке в случае серьезных ударов.",
	["GUIDE_TIP_255"] = "Слово силы: Барьер создает купол, защищающий всех, кто находится внутри, от вреда.",
	["GUIDE_TIP_256"] = "Раскол увеличивает урон, который вы наносите цели, что также увеличивает ваше исцеление.",
	["GUIDE_TIP_257"] = "Очищение снимает с ваших союзников неблагоприятные магические эффекты и болезни.",
	["GUIDE_TIP_258"] = "«Прыжок веры» привлекает к вам союзника; идеально подходит для спасения людей от пожара.",
	["GUIDE_TIP_259"] = "Flash Heal — это быстрое экстренное лечение для достижения индивидуальных целей.",
	["GUIDE_TIP_260"] = "«Слово Света: Безмятежность» — это мощное мгновенное исцеление с длительным временем восстановления, которое сокращается с помощью «Быстрого исцеления».",
	["GUIDE_TIP_261"] = "Holy Word: Sanctify — ваш лучший вариант для исцеления группы, находящейся в непосредственной близости.",
	["GUIDE_TIP_262"] = "Обновление обеспечивает постепенное исцеление; оставьте это активным на танке или игроках, которые получают постоянный урон.",
	["GUIDE_TIP_263"] = "«Молитва восстановления» переходит к другим союзникам, когда цель получает урон.",
	["GUIDE_TIP_264"] = "Божественный гимн — мощное заклинание, которое исцеляет всю группу и увеличивает получаемое ею исцеление.",
	["GUIDE_TIP_265"] = "Guardian Spirit увеличивает получаемое исцеление и предотвращает смерть цели.",
	["GUIDE_TIP_266"] = "Power Infusion значительно увеличивает вашу скорость; вы также можете надеть это на сильного игрока с ДПС.",
	["GUIDE_TIP_267"] = "Fade заставляет монстров временно игнорировать вас, если вы создали слишком большую угрозу.",
	["GUIDE_TIP_268"] = "Символ надежды восстанавливает часть маны всем целителям в вашей группе.",
	["GUIDE_TIP_269"] = "Слово Тьмы: Боль всегда должна сохраняться на всех ваших врагах.",
	["GUIDE_TIP_270"] = "Прикосновение вампира наносит постепенный урон и восстанавливает часть вашей жизни.",
	["GUIDE_TIP_271"] = "Mind Blast повышает безумие и наносит значительный прямой урон.",
	["GUIDE_TIP_272"] = "Пытка разума — ваше заклинание-наполнитель, которое замедляет врага, пока вы ждете других кулдаунов.",
	["GUIDE_TIP_273"] = "Вы можете использовать Стрелу Бездны только во время Облика Бездны; оно освежает продолжительность ваших болезней.",
	["GUIDE_TIP_274"] = "Слово Тьмы: Смерть — ваш финишер для врагов, находящихся на грани смерти.",
	["GUIDE_TIP_275"] = "Shadow Crash идеально подходит для применения Vampiric Touch к группам врагов.",
	["GUIDE_TIP_276"] = "Рассеивание снижает весь входящий урон на 75%; твой лучший способ выжить.",
	["GUIDE_TIP_277"] = "Shadowfiend вызывает существо, которое атакует вашего врага и генерирует для вас безумие.",
	["GUIDE_TIP_278"] = "Vampiric Embrace преобразует часть вашего урона в исцеление для всей группы.",
	["GUIDE_TIP_279"] = "Гаррота — ваше начало; он применяет кровотечение и генерирует комбо-очки.",
	["GUIDE_TIP_280"] = "Разрыв — ваш главный финишер; всегда держите это кровотечение активным на своей цели.",
	["GUIDE_TIP_281"] = "Backstab — это ваш строитель базы для очков комбо, когда вы находитесь позади цели.",
	["GUIDE_TIP_282"] = "Dispatch — ваш мощный финишер, когда у противника мало жизней.",
	["GUIDE_TIP_283"] = "Вендетта наносит вашему врагу дополнительный урон; используйте это для взрыва.",
	["GUIDE_TIP_284"] = "Vanish заставляет вас исчезнуть посреди боя; полезно для побега или повторного открытия.",
	["GUIDE_TIP_285"] = "Удар прерывает заклинания противника; необходимо для предотвращения повреждений.",
	["GUIDE_TIP_286"] = "Shadowstep позволяет вам появиться прямо за вашей целью.",
	["GUIDE_TIP_287"] = "Уклонение значительно увеличивает ваш шанс уклонения при получении физических ударов.",
	["GUIDE_TIP_288"] = "Плащ теней делает вас невосприимчивым к магии и снимает отрицательные эффекты.",
	["GUIDE_TIP_289"] = "Sinister Strike — ваша основная атака для накопления комбо-очков.",
	["GUIDE_TIP_290"] = "Roll the Bones дает вам случайные боевые бонусы; всегда держите это активным.",
	["GUIDE_TIP_291"] = "Потрошение — ваш стандартный финишер с высоким уроном.",
	["GUIDE_TIP_292"] = "Используйте «Выстрел из пистолета», когда загорается надпись «Возможность», чтобы получить бесплатные комбо-очки.",
	["GUIDE_TIP_293"] = "Blade Flurry гарантирует, что ваши атаки поражают всех ближайших врагов; идеально подходит для групп.",
	["GUIDE_TIP_294"] = "Адреналиновый прилив значительно увеличивает выработку энергии и скорость атаки.",
	["GUIDE_TIP_295"] = "Слепота дезориентирует противника на минуту; идеально подходит для контроля толпы.",
	["GUIDE_TIP_296"] = "Vanish — ваша аварийная кнопка, позволяющая избежать опасных ситуаций.",
	["GUIDE_TIP_297"] = "Пните этих надоедливых волшебников, чтобы остановить их заклинания.",
	["GUIDE_TIP_298"] = "Финт уменьшает урон, получаемый вами от атак по области (AoE).",
	["GUIDE_TIP_299"] = "Shadowstrike — ваш самый сильный дебют и средство для создания комбо-очков из Stealth или Shadow Dance.",
	["GUIDE_TIP_300"] = "Потрошение — ваш основной финишер, наносящий максимальный урон.",
	["GUIDE_TIP_301"] = "Черный порошок — ваш финишер для групп врагов.",
	["GUIDE_TIP_302"] = "Shadow Dance позволяет вам использовать скрытные атаки, не оставаясь невидимым.",
	["GUIDE_TIP_303"] = "Shadow Blades гарантирует, что ваши атаки нанесут дополнительный урон и принесут больше комбо-очков.",
	["GUIDE_TIP_304"] = "Сюрикен Торнадо идеально подходит для заражения сразу целой группы врагов.",
	["GUIDE_TIP_305"] = "Vanish сбрасывает ваши возможности скрытности в середине битвы.",
	["GUIDE_TIP_306"] = "Удар необходим, чтобы прервать врагов.",
	["GUIDE_TIP_307"] = "Выстрел в почки оглушает (оглушает) врага в зависимости от ваших очков комбо.",
	["GUIDE_TIP_308"] = "Плащ теней защищает вас от всех магических атак.",
	["GUIDE_TIP_309"] = "«Молния» — ваша базовая атака для создания Водоворота.",
	["GUIDE_TIP_310"] = "Цепная молния — ваше лучшее оружие против групп врагов.",
	["GUIDE_TIP_311"] = "Earth Shock — ваш мощный финишер; используйте его, когда ваш Водоворот почти полон.",
	["GUIDE_TIP_312"] = "«Выброс лавы» гарантированно нанесет критический урон, если на цели находится «Огненный шок».",
	["GUIDE_TIP_313"] = "Всегда держите «Огненный шок» активным на своих врагах, чтобы наносить постоянный урон.",
	["GUIDE_TIP_314"] = "Элементаль огня увеличивает урон от «Выброса лавы» и создает Водоворот.",
	["GUIDE_TIP_315"] = "Astral Shift снижает входящий урон на 40%; ваша главная защита.",
	["GUIDE_TIP_316"] = "Wind Shear — лучшее прерывание в игре; пользуйтесь им часто!",
	["GUIDE_TIP_317"] = "Тотем конденсатора оглушает всех ближайших врагов через 2 секунды.",
	["GUIDE_TIP_318"] = "Жажда крови (или героизм) значительно увеличивает скорость атаки всей группы.",
	["GUIDE_TIP_319"] = "Stormstrike — ваша основная атака; используйте его, как только он станет доступен.",
	["GUIDE_TIP_320"] = "Rockbiter создает Водоворот и усиливает ваши следующие атаки.",
	["GUIDE_TIP_321"] = "Lava Lash — ваша дополнительная атака, позволяющая потратить Водоворот.",
	["GUIDE_TIP_322"] = "Используйте Crash Lightning против групп, чтобы наносить и другие атаки по площади.",
	["GUIDE_TIP_323"] = "Огненный шок всегда должен быть на вашей цели, чтобы наносить дополнительный урон с течением времени.",
	["GUIDE_TIP_324"] = "Feral Spirit призывает двух волков, которые наносят вам урон и создают Водоворот.",
	["GUIDE_TIP_325"] = "Не забывайте Astral Shift для тяжелых ударов; это спасает вашу жизнь.",
	["GUIDE_TIP_326"] = "Wind Shear мгновенно заставит замолчать вражеских волшебников.",
	["GUIDE_TIP_327"] = "Используйте тотем конденсатора, чтобы получить передышку в больших группах.",
	["GUIDE_TIP_328"] = "Ghost Wolf поможет вам двигаться быстро и игнорировать задержки.",
	["GUIDE_TIP_329"] = "Riptide обеспечивает немедленное исцеление и сильное исцеление с течением времени.",
	["GUIDE_TIP_330"] = "Chain Heal – король группового исцеления; он прыгает к раненым союзникам.",
	["GUIDE_TIP_331"] = "«Волна исцеления» медленная, но эффективная; используйте это, когда урон невелик.",
	["GUIDE_TIP_332"] = "Healing Surge — это быстрое экстренное исцеление в критических ситуациях.",
	["GUIDE_TIP_333"] = "Тотем Исцеляющего потока обеспечивает пассивное исцеление группы, пока вы занимаетесь другими делами.",
	["GUIDE_TIP_334"] = "Тотем Духовой Связи выравнивает жизнь всех, кто находится рядом; настоящий спасатель жизни.",
	["GUIDE_TIP_335"] = "Используйте Astral Shift, чтобы получать меньше урона себе и исцелять других.",
	["GUIDE_TIP_336"] = "Как целитель, ваша работа — сдвиг ветра; прекрати эти заклинания!",
	["GUIDE_TIP_337"] = "Мастерство стихий значительно увеличивает вашу скорость, ускоряя исцеление.",
	["GUIDE_TIP_338"] = "Тотем «Исцеляющий прилив» — ваше самое сильное время восстановления группового исцеления; сохраните это для серьезного урона по площади.",
	["GUIDE_TIP_339"] = "Агония всегда должна быть на вашей цели; Чем дольше он тикает, тем больше и больше урона он наносит.",
	["GUIDE_TIP_340"] = "Порча — ваше основное проклятие, наносящее постоянный урон с течением времени.",
	["GUIDE_TIP_341"] = "Нестабильное колдовство — ваше самое сильное проклятие; одновременно у вас может быть только один активный.",
	["GUIDE_TIP_342"] = "Vile Taint идеально подходит для одновременного заражения целой группы врагов Агонией.",
	["GUIDE_TIP_343"] = "Malefic Rapture наносит огромный урон всем, на кого вы наложили проклятия.",
	["GUIDE_TIP_344"] = "Shadow Bolt — ваше заклинание-наполнитель для накопления осколков души.",
	["GUIDE_TIP_345"] = "Держите время восстановления Soul Rot готовым к нанесению дополнительного урона нескольким целям.",
	["GUIDE_TIP_346"] = "Soul Fire наносит значительный урон и мгновенно дает вам осколок души.",
	["GUIDE_TIP_347"] = "Демонический круг позволяет мгновенно телепортироваться обратно в безопасное место.",
	["GUIDE_TIP_348"] = "Не забудьте создать свой Камень здоровья; это ваше собственное бесплатное «зелье».",
	["GUIDE_TIP_349"] = "Рука Гул'дана поглощает ваши осколки души, чтобы вызвать диких бесов.",
	["GUIDE_TIP_350"] = "Вызов Dreadstalkers следует использовать сразу же, как только закончится время восстановления.",
	["GUIDE_TIP_351"] = "Демоническая стрела генерирует 2 осколка души; используйте его, когда загорается «Демоническое ядро».",
	["GUIDE_TIP_352"] = "Призыв демонического тирана увеличивает продолжительность действия всех ваших активных демонов и делает их сильнее.",
	["GUIDE_TIP_353"] = "Имплозия взрывает всех ваших бесов, нанося огромный урон группам врагов.",
	["GUIDE_TIP_354"] = "Shadow Bolt — ваш основной способ сбора осколков души.",
	["GUIDE_TIP_355"] = "Демоническая сила позволяет вашему стражу Скверны выполнять мощный подсчет ходов.",
	["GUIDE_TIP_356"] = "Гримуар: Страж Скверны призывает второго стража для дополнительного урона и оглушения.",
	["GUIDE_TIP_357"] = "Бесконечная решимость уменьшает входящий урон и предотвращает прерывание ваших заклинаний.",
	["GUIDE_TIP_358"] = "Держите своего Странника Бездны активным во время прокачки, чтобы он принял на себя все удары.",
	["GUIDE_TIP_359"] = "«Стрела Хаоса» — ваша самая сильная атака; используйте его, чтобы сбросить фрагменты осколков души.",
	["GUIDE_TIP_360"] = "Сжигание — ваш заполнитель для создания фрагментов осколков души.",
	["GUIDE_TIP_361"] = "Поджигание действует мгновенно и дает вам «Обратную тягу», ускоряя ваши последующие заклинания.",
	["GUIDE_TIP_362"] = "Жертвенный огонь всегда должен гореть на вашем враге, нанося постоянный урон и дополнительные фрагменты.",
	["GUIDE_TIP_363"] = "Призыв Инфернала — ваше большое время восстановления; он проливает огонь и парализует врагов при ударе.",
	["GUIDE_TIP_364"] = "Огненный дождь — ваше лучшее оружие против больших групп врагов.",
	["GUIDE_TIP_365"] = "Shadowburn идеально подходит для быстрого уничтожения врагов с небольшим количеством жизни.",
	["GUIDE_TIP_366"] = "Havoc также позволяет вашим заклинаниям поразить вторую цель; необходим для нанесения «раскалывающего» урона.",
	["GUIDE_TIP_367"] = "Команда «Демон» позволяет вам использовать особую способность вашего активного демона.",
	["GUIDE_TIP_368"] = "Используйте «Бесконечную решимость», когда знаете, что приближается большой удар.",
	["GUIDE_TIP_369"] = "«Смертельный удар» — ваш самый сильный удар; используйте его как можно скорее, чтобы потратить Ярость.",
	["GUIDE_TIP_370"] = "От способности «Превосходство» нельзя уклониться, и она усиливает ваш следующий «Смертельный удар».",
	["GUIDE_TIP_371"] = "Colossus Smash пробивает броню вашего врага, нанося огромный урон.",
	["GUIDE_TIP_372"] = "«Казнь» — ваш смертельный финишер для врагов, у которых осталось менее 20% здоровья.",
	["GUIDE_TIP_373"] = "Bladestorm превращает вас в стальной вихрь; идеально подходит для групп врагов.",
	["GUIDE_TIP_374"] = "Slam — это ваша дополнительная атака, если у вас слишком много ярости, а другие атаки находятся в процессе восстановления.",
	["GUIDE_TIP_375"] = "Умереть от меча — ваша лучшая защита; он блокирует почти все физические атаки.",
	["GUIDE_TIP_376"] = "Pummel прерывает заклинания противника; не позволяйте этим волшебникам кастовать!",
	["GUIDE_TIP_377"] = "Storm Bolt парализует (оглушает) врага на расстоянии; полезно, чтобы остановить опасность.",
	["GUIDE_TIP_378"] = "Рывок — лучший способ немедленно начать бой и накопить ярость.",
	["GUIDE_TIP_379"] = "Буйство — ваша основная атака; это приводит вас в ярость из-за дополнительной скорости и урона.",
	["GUIDE_TIP_380"] = "Кровожадность немного лечит вас и является вашим основным источником ярости.",
	["GUIDE_TIP_381"] = "Raging Blow наносит значительный урон и часто может быть использован дважды подряд.",
	["GUIDE_TIP_382"] = "Казнь накапливает массу ярости и наносит тяжелый урон слабым врагам.",
	["GUIDE_TIP_383"] = "Безрассудство — ваше большое время восстановления; вы получаете на 100% больше ярости и намного больше критических ударов.",
	["GUIDE_TIP_384"] = "«Вихрь» заставляет ваши следующие 2 атаки поразить несколько врагов; необходим для AoE.",
	["GUIDE_TIP_385"] = "Яростная регенерация отлично исцеляет вас, пока вы продолжаете использовать Кровожадность.",
	["GUIDE_TIP_386"] = "Используйте Pummel, чтобы мгновенно остановить надоедливые вражеские заклинания.",
	["GUIDE_TIP_387"] = "Piercing Howl замедляет всех врагов вокруг вас; полезно для контроля.",
	["GUIDE_TIP_388"] = "Heroic Leap позволяет преодолевать большие расстояния; идеально подходит для мобильности.",
	["GUIDE_TIP_389"] = "Shield Slam — ваша самая сильная угрожающая атака, вызывающая много ярости.",
	["GUIDE_TIP_390"] = "Thunder Clap замедляет врагов и удерживает группы монстров от вас.",
	["GUIDE_TIP_391"] = "Месть наносит сильный ответный удар после блока или уклонения; бесплатный урон против групп.",
	["GUIDE_TIP_392"] = "Блок щитом всегда должен быть активен при получении физических ударов от монстров.",
	["GUIDE_TIP_393"] = "«Игнорировать боль» поглощает большую часть входящего урона; используйте для этого свою Ярость.",
	["GUIDE_TIP_394"] = "Аватар превращает вас в гиганта; вы наносите больше урона и выходите из задержек.",
	["GUIDE_TIP_395"] = "Стена щитов — ваша самая сильная защита; используйте это, если что-то действительно грозит пойти не так.",
	["GUIDE_TIP_396"] = "Last Stand временно увеличивает ваше максимальное количество жизни; ваша лучшая кнопка экстренной помощи.",
	["GUIDE_TIP_397"] = "Pummel необходим для того, чтобы подтолкнуть волшебников к вам, остановив их заклинания.",
	["GUIDE_TIP_398"] = "Перехват (или Рывок) помогает быстро добраться до врагов или союзников.",
})
